QUESTIONS.push(

  // ================= Hardware Basics (50) =================
  { id: "hw-01", topic: "os-hardware", q: "The Von Neumann architecture stores:", options: ["Programs and data in separate memories", "Programs and data in the same memory", "Only data in memory", "Programs in registers"], answer: 1, exp: "A single shared memory holds both instructions and data (contrast with Harvard architecture)." },
  { id: "hw-02", topic: "os-hardware", q: "The 'Von Neumann bottleneck' refers to:", options: ["Slow disk I/O", "The limited bandwidth of the single bus between CPU and memory", "Too few registers", "Cache misses only"], answer: 1, exp: "The CPU can process faster than the shared memory bus can supply instructions and data." },
  { id: "hw-03", topic: "os-hardware", q: "The two main components of a CPU are:", options: ["Cache and RAM", "The ALU (arithmetic logic unit) and the control unit", "Disk and bus", "Registers and I/O ports"], answer: 1, exp: "The ALU performs computation; the control unit fetches, decodes and sequences instructions." },
  { id: "hw-04", topic: "os-hardware", q: "The program counter (PC / instruction pointer) holds:", options: ["The result of the last operation", "The address of the next instruction to execute", "The current instruction", "The stack top"], answer: 1, exp: "After a fetch it is incremented (or set by a branch)." },
  { id: "hw-05", topic: "os-hardware", q: "The basic instruction cycle is:", options: ["Fetch, decode, execute (, write-back)", "Load, store, jump", "Read, compute, sleep", "Compile, link, run"], answer: 0, exp: "Fetch the instruction, decode it, execute it, then write results / update the PC." },
  { id: "hw-06", topic: "os-hardware", q: "Which memory is fastest and smallest?", options: ["Main memory (RAM)", "CPU registers", "L3 cache", "SSD"], answer: 1, exp: "The memory hierarchy from fastest/smallest to slowest/largest: registers, L1/L2/L3 cache, RAM, SSD/disk." },
  { id: "hw-07", topic: "os-hardware", q: "Cache memory exploits:", options: ["Only temporal locality", "Only spatial locality", "Both temporal and spatial locality of reference", "Random access patterns"], answer: 2, exp: "Recently used data is reused (temporal); nearby data is loaded as a block/line (spatial)." },
  { id: "hw-08", topic: "os-hardware", q: "SRAM vs DRAM: DRAM is:", options: ["Faster and used for cache", "Denser, cheaper, needs periodic refresh, used for main memory", "Non-volatile", "Used only in registers"], answer: 1, exp: "SRAM (6 transistors/bit) is fast and used for cache; DRAM (1 transistor + capacitor) is dense but must be refreshed." },
  { id: "hw-09", topic: "os-hardware", q: "Volatile memory:", options: ["Retains data without power", "Loses its contents when power is removed (RAM)", "Is always read-only", "Is the same as ROM"], answer: 1, exp: "RAM is volatile; ROM, flash and disk are non-volatile." },
  { id: "hw-10", topic: "os-hardware", q: "A 32-bit processor can directly address at most:", options: ["2^16 bytes", "2^32 bytes = 4 GB", "2^64 bytes", "unlimited memory"], answer: 1, exp: "The address bus width bounds the addressable space; 2^32 = 4 GiB." },
  { id: "hw-11", topic: "os-hardware", q: "Pipelining improves CPU performance by:", options: ["Running instructions slower but correctly", "Overlapping the fetch/decode/execute stages of consecutive instructions", "Adding more memory", "Removing the control unit"], answer: 1, exp: "An ideal k-stage pipeline approaches a k-fold throughput speedup." },
  { id: "hw-12", topic: "os-hardware", q: "A pipeline hazard is:", options: ["A cache miss", "A situation (data, control, or structural dependency) that stalls the pipeline", "An interrupt", "A power failure"], answer: 1, exp: "Data hazards (RAW), control hazards (branches), and structural hazards (resource conflicts)." },
  { id: "hw-13", topic: "os-hardware", q: "Branch prediction is used to mitigate:", options: ["Data hazards", "Control (branch) hazards by guessing the branch outcome early", "Cache misses", "Bus contention"], answer: 1, exp: "A mispredict flushes the wrongly-fetched instructions." },
  { id: "hw-14", topic: "os-hardware", q: "An interrupt is:", options: ["A software bug", "A signal that diverts the CPU to a handler, saving the current context", "A type of cache", "A scheduling algorithm"], answer: 1, exp: "Hardware interrupts (I/O, timer) and software interrupts / exceptions / traps all transfer control to the OS." },
  { id: "hw-15", topic: "os-hardware", q: "DMA (Direct Memory Access) allows:", options: ["The CPU to access disk directly", "An I/O device to transfer data to/from memory without CPU involvement per byte", "Faster cache", "Virtual memory"], answer: 1, exp: "The CPU sets up the transfer, then the DMA controller moves the block and interrupts on completion." },
  { id: "hw-16", topic: "os-hardware", q: "Memory-mapped I/O means:", options: ["I/O devices use special CPU instructions", "Device registers are assigned addresses in the normal memory address space", "I/O is done via files", "The disk is mapped to RAM"], answer: 1, exp: "The CPU reads/writes device registers with ordinary load/store instructions (vs isolated / port-mapped I/O)." },
  { id: "hw-17", topic: "os-hardware", q: "The system bus typically consists of:", options: ["Only a data bus", "Address bus, data bus and control bus", "Cache and registers", "The CPU and RAM"], answer: 1, exp: "Address lines select a location, data lines carry the value, control lines carry read/write and timing signals." },
  { id: "hw-18", topic: "os-hardware", q: "A word (in computer architecture) is:", options: ["Always 8 bits", "The natural unit of data for a given processor (e.g. 32 or 64 bits)", "One character", "One instruction"], answer: 1, exp: "Word size usually equals the register width and the ALU's operand size." },
  { id: "hw-19", topic: "os-hardware", q: "Little-endian byte order stores:", options: ["The most significant byte at the lowest address", "The least significant byte at the lowest address", "Bytes in random order", "Only in big memory"], answer: 1, exp: "x86 is little-endian; many network protocols use big-endian ('network byte order')." },
  { id: "hw-20", topic: "os-hardware", q: "RISC architectures are characterized by:", options: ["Many complex, variable-length instructions", "A small set of simple, fixed-length instructions with load/store memory access", "No registers", "Microcode for every instruction"], answer: 1, exp: "RISC (ARM, RISC-V) favors pipelining and compiler optimization; CISC (x86) has richer instructions." },
  { id: "hw-21", topic: "os-hardware", q: "The clock speed (e.g. 3 GHz) indicates:", options: ["Instructions per second exactly", "Clock cycles per second; actual throughput also depends on CPI/IPC", "Memory size", "Number of cores"], answer: 1, exp: "Performance = clock rate x IPC (instructions per cycle); a higher clock is not automatically faster." },
  { id: "hw-22", topic: "os-hardware", q: "A multicore processor has:", options: ["One CPU that runs faster", "Multiple independent processing units on one chip, enabling true parallelism", "More cache only", "A bigger clock"], answer: 1, exp: "Each core can execute a separate thread simultaneously." },
  { id: "hw-23", topic: "os-hardware", q: "Hyper-threading / SMT (simultaneous multithreading):", options: ["Doubles the number of physical cores", "Lets one physical core run 2+ hardware threads, sharing execution units to hide stalls", "Is the same as multicore", "Disables the cache"], answer: 1, exp: "It improves utilization when one thread stalls on memory." },
  { id: "hw-24", topic: "os-hardware", q: "Cache write-through vs write-back: write-back:", options: ["Writes to memory immediately on every store", "Writes only to cache, deferring the memory update until the line is evicted (marked dirty)", "Never writes to memory", "Is slower"], answer: 1, exp: "Write-back reduces memory traffic but needs a dirty bit and careful coherence handling." },
  { id: "hw-25", topic: "os-hardware", q: "Cache coherence protocols (e.g. MESI) ensure:", options: ["Caches are large", "All cores see a consistent view of shared memory despite private caches", "Faster clock speeds", "No cache misses"], answer: 1, exp: "MESI = Modified, Exclusive, Shared, Invalid states per cache line." },
  { id: "hw-26", topic: "os-hardware", q: "A page fault is handled by:", options: ["The compiler", "The CPU raising an exception that the OS's memory manager services", "The disk controller alone", "The cache"], answer: 1, exp: "The MMU detects the missing page; the OS loads it from disk and resumes the instruction." },
  { id: "hw-27", topic: "os-hardware", q: "The MMU (Memory Management Unit) performs:", options: ["Arithmetic", "Virtual-to-physical address translation and protection checks", "Instruction decoding", "Branch prediction"], answer: 1, exp: "It uses page tables (cached in the TLB) to map virtual addresses." },
  { id: "hw-28", topic: "os-hardware", q: "The TLB (Translation Lookaside Buffer) is:", options: ["A disk cache", "A small fast cache of recent virtual-to-physical page translations", "A branch predictor", "A register file"], answer: 1, exp: "A TLB hit avoids a slow multi-level page-table walk." },
  { id: "hw-29", topic: "os-hardware", q: "Which storage is non-volatile AND byte-addressable AND faster than SSD?", options: ["DRAM", "Persistent memory (e.g. NVDIMM / Intel Optane)", "Magnetic tape", "L1 cache"], answer: 1, exp: "Persistent memory sits between DRAM and SSD in the hierarchy." },
  { id: "hw-30", topic: "os-hardware", q: "SSD vs HDD: an SSD has:", options: ["Moving parts and higher latency", "No moving parts, much lower access latency, limited write endurance", "Larger capacity always", "Slower sequential reads"], answer: 1, exp: "Flash cells wear out after many program/erase cycles; wear leveling spreads writes." },
  { id: "hw-31", topic: "os-hardware", q: "RAID 0 provides:", options: ["Mirroring for redundancy", "Striping for performance, with NO redundancy", "Parity across drives", "Both mirroring and striping"], answer: 1, exp: "RAID 0 splits data across disks for speed; one drive failure loses everything." },
  { id: "hw-32", topic: "os-hardware", q: "RAID 1 provides:", options: ["Striping only", "Mirroring — an exact copy on a second drive", "Distributed parity", "No redundancy"], answer: 1, exp: "Survives one drive failure; usable capacity is halved." },
  { id: "hw-33", topic: "os-hardware", q: "RAID 5 uses:", options: ["Mirroring", "Block-level striping with distributed parity — survives one drive failure", "Two parity blocks", "No parity"], answer: 1, exp: "RAID 6 adds a second parity block to survive two failures." },
  { id: "hw-34", topic: "os-hardware", q: "A GPU is well suited to:", options: ["Sequential, branchy control-flow code", "Massively data-parallel workloads (SIMD) like graphics and matrix math", "Running the OS kernel", "Low-latency single-thread tasks"], answer: 1, exp: "Thousands of simple cores execute the same operation on many data elements." },
  { id: "hw-35", topic: "os-hardware", q: "The fetch-decode-execute cycle is driven by:", options: ["The user", "The system clock", "Interrupts only", "The cache"], answer: 1, exp: "Each clock tick (or set of ticks) advances the CPU through instruction stages." },
  { id: "hw-36", topic: "os-hardware", q: "An instruction set architecture (ISA) defines:", options: ["The physical chip layout", "The interface between hardware and software — instructions, registers, addressing modes", "The clock speed", "The number of transistors"], answer: 1, exp: "x86-64, ARM and RISC-V are ISAs; microarchitecture is a specific implementation of an ISA." },
  { id: "hw-37", topic: "os-hardware", q: "Which is TRUE about registers vs cache?", options: ["Cache is faster than registers", "Registers are explicitly named in instructions; cache is transparent to the programmer", "They are the same", "Registers are on disk"], answer: 1, exp: "The compiler allocates registers; hardware manages the cache automatically." },
  { id: "hw-38", topic: "os-hardware", q: "Direct-mapped cache maps a memory block to:", options: ["Any cache line", "Exactly one cache line (block address mod number of lines)", "One of a few lines in a set", "The first free line"], answer: 1, exp: "Simple and fast but prone to conflict misses; set-associative and fully-associative are more flexible." },
  { id: "hw-39", topic: "os-hardware", q: "The three types of cache miss are:", options: ["Read, write, execute", "Compulsory (cold), capacity, conflict", "L1, L2, L3", "Hit, near-hit, far-hit"], answer: 1, exp: "The '3 Cs' model: first access, cache too small, and mapping collisions." },
  { id: "hw-40", topic: "os-hardware", q: "A firmware / BIOS / UEFI is stored in:", options: ["RAM", "Non-volatile flash/ROM on the motherboard", "The CPU cache", "The hard disk's boot sector only"], answer: 1, exp: "It runs at power-on to initialize hardware and load the bootloader." },
  { id: "hw-41", topic: "os-hardware", q: "The purpose of a heat sink and fan is to:", options: ["Increase clock speed", "Dissipate heat so the CPU stays within safe thermal limits (avoiding throttling)", "Store data", "Reduce power draw"], answer: 1, exp: "Thermal throttling reduces the clock when a chip gets too hot." },
  { id: "hw-42", topic: "os-hardware", q: "A bus arbiter is needed when:", options: ["There is one bus master", "Multiple devices may want to drive a shared bus at once", "The bus is idle", "Memory is full"], answer: 1, exp: "It grants the bus to one master at a time to prevent contention." },
  { id: "hw-43", topic: "os-hardware", q: "Polling vs interrupt-driven I/O: polling:", options: ["Is more CPU-efficient", "Repeatedly checks the device status, wasting CPU cycles while waiting", "Uses no CPU", "Requires DMA"], answer: 1, exp: "Interrupt-driven I/O lets the CPU do other work until the device signals readiness." },
  { id: "hw-44", topic: "os-hardware", q: "The 'clock' in a synchronous digital circuit:", options: ["Displays the time", "Provides a periodic signal that synchronizes state changes across the circuit", "Is optional", "Stores data"], answer: 1, exp: "All flip-flops update on the clock edge." },
  { id: "hw-45", topic: "os-hardware", q: "Amdahl's law states that the speedup from parallelizing a program is limited by:", options: ["The number of cores only", "The fraction of the program that remains sequential", "The clock speed", "The cache size"], answer: 1, exp: "If 10% is serial, the maximum speedup is 10x no matter how many cores." },
  { id: "hw-46", topic: "os-hardware", q: "A 64-bit CPU register can hold an unsigned integer up to:", options: ["2^32 - 1", "2^64 - 1", "2^16 - 1", "10^64"], answer: 1, exp: "64 bits => values 0 to 2^64 - 1 (about 1.8 x 10^19)." },
  { id: "hw-47", topic: "os-hardware", q: "Which component decodes the instruction and generates control signals?", options: ["The ALU", "The control unit", "The register file", "The cache"], answer: 1, exp: "The control unit orchestrates the datapath for each instruction (hardwired or microcoded)." },
  { id: "hw-48", topic: "os-hardware", q: "Locality of reference is important because:", options: ["It makes code shorter", "It is what makes caching and paging effective", "It reduces the instruction count", "It prevents deadlock"], answer: 1, exp: "Programs tend to reuse recent addresses and access nearby ones, which the memory hierarchy exploits." },
  { id: "hw-49", topic: "os-hardware", q: "A superscalar processor:", options: ["Has a very high clock", "Issues multiple instructions per clock cycle to parallel execution units", "Has only one core", "Runs at 5 GHz"], answer: 1, exp: "It exploits instruction-level parallelism within a single thread." },
  { id: "hw-50", topic: "os-hardware", q: "The primary role of an operating system with respect to hardware is to:", options: ["Replace the hardware", "Abstract and manage hardware resources (CPU, memory, I/O) and provide a safe interface to programs", "Speed up the clock", "Compile programs"], answer: 1, exp: "The OS is the resource manager and the hardware/application intermediary." },

  // ================= Processes (50) =================
  { id: "pr-01", topic: "os-processes", q: "A process is:", options: ["A program stored on disk", "A program in execution, with its own address space and resources", "A function call", "A thread"], answer: 1, exp: "A program is passive (a file); a process is active, with a PC, stack, heap, data, and OS-tracked state." },
  { id: "pr-02", topic: "os-processes", q: "The Process Control Block (PCB) stores:", options: ["Only the process name", "Process state, PC, registers, memory limits, open files, scheduling info, PID", "The source code", "Only the priority"], answer: 1, exp: "The PCB is the OS's per-process record, saved/restored on a context switch." },
  { id: "pr-03", topic: "os-processes", q: "The five classic process states are:", options: ["New, Ready, Running, Waiting (Blocked), Terminated", "Start, Middle, End", "Fork, Exec, Wait, Exit, Kill", "Active, Idle, Sleep"], answer: 0, exp: "Transitions: admitted, dispatch, timeout, I/O request, I/O complete, exit." },
  { id: "pr-04", topic: "os-processes", q: "A process moves from Running to Ready when:", options: ["It requests I/O", "Its time quantum expires (preemption) or a higher-priority process arrives", "It terminates", "It is created"], answer: 1, exp: "Running -> Waiting on I/O; Running -> Ready on preemption." },
  { id: "pr-05", topic: "os-processes", q: "A process moves from Running to Waiting (Blocked) when:", options: ["Its quantum expires", "It requests an I/O operation or waits on an event/semaphore", "It is dispatched", "It is admitted"], answer: 1, exp: "It cannot proceed until the event completes, then it becomes Ready." },
  { id: "pr-06", topic: "os-processes", q: "A context switch involves:", options: ["Only changing the PC", "Saving the running process's state to its PCB and loading another's state", "Restarting the computer", "Freeing all memory"], answer: 1, exp: "It is pure overhead — no useful work is done during the switch." },
  { id: "pr-07", topic: "os-processes", q: "The fork() system call:", options: ["Replaces the current process image", "Creates a child process that is a copy of the parent; returns 0 to the child, the child's PID to the parent", "Terminates the process", "Creates a thread"], answer: 1, exp: "After fork() both processes run the same code from the point of the call." },
  { id: "pr-08", topic: "os-processes", q: "The exec() family of system calls:", options: ["Creates a new process", "Replaces the current process's memory image with a new program (same PID)", "Duplicates the process", "Blocks the process"], answer: 1, exp: "fork() + exec() is the standard way to run a new program." },
  { id: "pr-09", topic: "os-processes", q: "A zombie process is:", options: ["A process using 100% CPU", "A terminated child whose exit status has not yet been read (wait()ed) by its parent", "A process stuck in an infinite loop", "A malicious process"], answer: 1, exp: "The PCB lingers until the parent reaps it; then it is removed." },
  { id: "pr-10", topic: "os-processes", q: "An orphan process is:", options: ["A process with no memory", "A process whose parent terminated before it; it is adopted by init (PID 1)", "A zombie", "A daemon"], answer: 1, exp: "init periodically wait()s to reap adopted orphans when they exit." },
  { id: "pr-11", topic: "os-processes", q: "The wait() system call:", options: ["Sleeps for a fixed time", "Blocks the parent until a child terminates, returning its exit status", "Creates a child", "Sends a signal"], answer: 1, exp: "It also reaps the child, preventing a zombie." },
  { id: "pr-12", topic: "os-processes", q: "A process's address space is typically divided into:", options: ["Only stack and heap", "Text (code), data, heap (grows up), stack (grows down)", "Registers and cache", "Kernel and user only"], answer: 1, exp: "The gap between heap and stack allows both to grow." },
  { id: "pr-13", topic: "os-processes", q: "The 'ready queue' holds processes that are:", options: ["Waiting for I/O", "In memory and ready to run, waiting for the CPU", "Terminated", "Swapped out to disk"], answer: 1, exp: "The short-term scheduler picks from the ready queue." },
  { id: "pr-14", topic: "os-processes", q: "The long-term scheduler (job scheduler) controls:", options: ["Which ready process runs next", "The degree of multiprogramming — which jobs are admitted into memory", "Context switches", "Page replacement"], answer: 1, exp: "It runs infrequently and balances I/O-bound and CPU-bound jobs." },
  { id: "pr-15", topic: "os-processes", q: "The short-term scheduler (CPU scheduler):", options: ["Runs rarely", "Selects which ready process gets the CPU next; runs very frequently (ms)", "Admits new jobs", "Swaps processes to disk"], answer: 1, exp: "It must be fast because it runs on every scheduling decision." },
  { id: "pr-16", topic: "os-processes", q: "Medium-term scheduling performs:", options: ["Instruction fetch", "Swapping — moving processes out of / back into memory to relieve memory pressure", "Interrupt handling", "Disk scheduling"], answer: 1, exp: "It reduces the degree of multiprogramming temporarily." },
  { id: "pr-17", topic: "os-processes", q: "A CPU-bound process:", options: ["Spends most time waiting for I/O", "Spends most time doing computation, needs long CPU bursts", "Never uses the CPU", "Is always high priority"], answer: 1, exp: "I/O-bound processes have short CPU bursts and frequent I/O waits." },
  { id: "pr-18", topic: "os-processes", q: "The dispatcher's job is to:", options: ["Choose the next process", "Give control of the CPU to the process chosen by the scheduler (context switch, switch to user mode, jump to the right location)", "Handle page faults", "Allocate memory"], answer: 1, exp: "Dispatch latency = time to stop one process and start another." },
  { id: "pr-19", topic: "os-processes", q: "A system call causes a transition from:", options: ["User mode to kernel mode", "Kernel mode to user mode", "Running to Ready", "Ready to Running"], answer: 0, exp: "A trap instruction switches the CPU to privileged (kernel) mode to run OS code safely." },
  { id: "pr-20", topic: "os-processes", q: "The exit() system call:", options: ["Creates a child", "Terminates the process, releasing resources; the exit status is available to the parent via wait()", "Blocks the process", "Forks"], answer: 1, exp: "Open files are closed and memory is reclaimed." },
  { id: "pr-21", topic: "os-processes", q: "Which is NOT part of a process's context saved on a switch?", options: ["CPU registers", "Program counter", "The source code file on disk", "Memory management info (page table base)"], answer: 2, exp: "The on-disk executable is not part of the runtime context." },
  { id: "pr-22", topic: "os-processes", q: "A daemon (or service) process is:", options: ["A process that runs in the background, often started at boot, with no controlling terminal", "A malicious process", "A zombie", "A foreground app"], answer: 0, exp: "Examples: sshd, cron, httpd." },
  { id: "pr-23", topic: "os-processes", q: "Cooperating processes:", options: ["Never interact", "Can affect or be affected by other processes; they share data and need IPC + synchronization", "Are always in the same address space", "Cannot be scheduled"], answer: 1, exp: "Independent processes do not share data; cooperating ones do." },
  { id: "pr-24", topic: "os-processes", q: "The PID (process identifier) is:", options: ["The process priority", "A unique number the OS assigns to identify the process", "The parent's name", "The memory size"], answer: 1, exp: "PID 1 is init/systemd on Unix." },
  { id: "pr-25", topic: "os-processes", q: "After fork(), the child and parent:", options: ["Share the same memory", "Have separate copies of the address space (often via copy-on-write)", "Run as one process", "Cannot both continue"], answer: 1, exp: "COW defers the actual copy until one of them writes to a page." },
  { id: "pr-26", topic: "os-processes", q: "Copy-on-write (COW) after fork means:", options: ["Pages are copied immediately", "Parent and child share physical pages read-only; a copy is made only when one writes", "The child cannot write", "Memory is doubled instantly"], answer: 1, exp: "This makes fork() cheap when followed quickly by exec()." },
  { id: "pr-27", topic: "os-processes", q: "A process in the 'new' state:", options: ["Is running", "Is being created and not yet admitted to the ready queue", "Has terminated", "Is blocked on I/O"], answer: 1, exp: "The long-term scheduler admits it, moving it to Ready." },
  { id: "pr-28", topic: "os-processes", q: "Which event moves a process from Waiting to Ready?", options: ["Its time quantum expires", "The I/O or event it was waiting for completes", "It is created", "It calls exit()"], answer: 1, exp: "It rejoins the ready queue to compete for the CPU." },
  { id: "pr-29", topic: "os-processes", q: "The degree of multiprogramming is:", options: ["The number of CPUs", "The number of processes in memory", "The clock speed", "The page size"], answer: 1, exp: "Too high causes thrashing; too low underutilizes the CPU." },
  { id: "pr-30", topic: "os-processes", q: "A process's turnaround time is:", options: ["Time spent running only", "Completion time minus arrival time (total time in the system)", "Time waiting in the ready queue", "Response time"], answer: 1, exp: "Waiting time = turnaround - burst time; response time = first-run time - arrival." },
  { id: "pr-31", topic: "os-processes", q: "Signals (SIGKILL, SIGTERM, SIGSTOP) are:", options: ["A form of shared memory", "Asynchronous notifications delivered to a process, a lightweight IPC / control mechanism", "System calls", "Interrupts from hardware only"], answer: 1, exp: "SIGKILL and SIGSTOP cannot be caught or ignored." },
  { id: "pr-32", topic: "os-processes", q: "The difference between SIGTERM and SIGKILL:", options: ["None", "SIGTERM asks the process to terminate gracefully (catchable); SIGKILL forcibly kills it (uncatchable)", "SIGKILL is slower", "SIGTERM restarts the process"], answer: 1, exp: "Send SIGTERM first, then SIGKILL if it does not exit." },
  { id: "pr-33", topic: "os-processes", q: "A process becomes a zombie for the time between:", options: ["fork() and exec()", "its termination and its parent calling wait()", "admission and dispatch", "a page fault and its resolution"], answer: 1, exp: "The kernel keeps the exit code and PID until reaped." },
  { id: "pr-34", topic: "os-processes", q: "The kernel maintains, for each process, a:", options: ["Compiler", "PCB in a process table", "Cache line", "Register window"], answer: 1, exp: "The process table indexes all PCBs." },
  { id: "pr-35", topic: "os-processes", q: "Preemptive scheduling means:", options: ["A process runs until it blocks or exits", "The OS can forcibly take the CPU away from a running process", "Processes cannot be interrupted", "There is only one process"], answer: 1, exp: "Non-preemptive (cooperative) scheduling relies on processes yielding." },
  { id: "pr-36", topic: "os-processes", q: "The idle process runs when:", options: ["The system is booting only", "No other process is ready to run", "The CPU is overloaded", "An interrupt occurs"], answer: 1, exp: "It keeps the CPU occupied (often halting to save power) until work arrives." },
  { id: "pr-37", topic: "os-processes", q: "Which is TRUE about processes vs programs?", options: ["They are identical", "One program can have many processes running it; a process is one execution instance", "A process has no state", "A program is always running"], answer: 1, exp: "e.g. multiple instances of a text editor." },
  { id: "pr-38", topic: "os-processes", q: "A process control operation that suspends a process and moves it to disk is:", options: ["Context switch", "Swap-out (by the medium-term scheduler)", "fork", "exec"], answer: 1, exp: "Swap-in returns it to memory later." },
  { id: "pr-39", topic: "os-processes", q: "The system boots by:", options: ["Running all user programs at once", "Firmware -> bootloader -> kernel -> init/systemd -> user space", "Loading the OS from RAM", "Starting the scheduler first"], answer: 1, exp: "init (PID 1) is the ancestor of all user processes." },
  { id: "pr-40", topic: "os-processes", q: "Which resource is NOT typically shared between a parent and child process after fork()?", options: ["Open file descriptors (shared, referring to the same file table entry)", "The address space (separate copies)", "Environment variables (copied)", "The user ID"], answer: 1, exp: "File descriptors are duplicated but point to the same open-file description; memory is a private copy." },
  { id: "pr-41", topic: "os-processes", q: "A process is 'starved' when:", options: ["It uses too much memory", "It is perpetually denied the CPU because higher-priority processes keep arriving", "It has no children", "It is a zombie"], answer: 1, exp: "Aging (gradually raising a waiting process's priority) prevents starvation." },
  { id: "pr-42", topic: "os-processes", q: "In a multiprocessor system, process affinity means:", options: ["Processes like each other", "Trying to keep a process running on the same CPU to preserve its cache state", "All processes on CPU 0", "Random assignment"], answer: 1, exp: "Migrating a process invalidates its warm cache on the old core." },
  { id: "pr-43", topic: "os-processes", q: "The 'text' segment of a process is:", options: ["Writable string data", "The read-only machine code, often shared between processes running the same program", "The stack", "Environment variables"], answer: 1, exp: "Sharing the text segment saves memory." },
  { id: "pr-44", topic: "os-processes", q: "Which system call sends a signal to a process?", options: ["fork()", "kill(pid, sig)", "wait()", "exec()"], answer: 1, exp: "Despite the name, kill() can send any signal, not just SIGKILL." },
  { id: "pr-45", topic: "os-processes", q: "A process's 'nice' value (Unix) affects:", options: ["Its memory limit", "Its scheduling priority (higher nice = lower priority, 'nicer' to others)", "Its PID", "Its file permissions"], answer: 1, exp: "Range typically -20 (highest priority) to +19." },
  { id: "pr-46", topic: "os-processes", q: "The three-state model (Running, Ready, Blocked) omits which two states of the five-state model?", options: ["New and Terminated", "Waiting and Running", "Ready and Blocked", "Swapped and Idle"], answer: 0, exp: "The five-state model adds New (being created) and Terminated (finished)." },
  { id: "pr-47", topic: "os-processes", q: "vfork() differs from fork() in that:", options: ["It creates a thread", "The child shares the parent's address space and the parent is suspended until the child exec()s or exits", "It is slower", "It cannot be followed by exec"], answer: 1, exp: "A historical optimization; largely superseded by copy-on-write fork()." },
  { id: "pr-48", topic: "os-processes", q: "A process makes a blocking system call. The CPU:", options: ["Idles until the call returns", "Is given to another ready process by the scheduler", "Restarts the process", "Terminates the process"], answer: 1, exp: "The process moves to Blocked; the CPU does useful work elsewhere." },
  { id: "pr-49", topic: "os-processes", q: "Which is the correct order of a typical process lifecycle?", options: ["New -> Ready -> Running -> (Waiting <-> Ready) -> Terminated", "Running -> New -> Ready -> Terminated", "Ready -> Terminated -> Running", "New -> Terminated -> Ready"], answer: 0, exp: "It may cycle between Running, Ready and Waiting many times before Terminated." },
  { id: "pr-50", topic: "os-processes", q: "The main cost of having many processes (vs threads) for a parallel task is:", options: ["They cannot run in parallel", "Higher memory use (separate address spaces) and more expensive creation / context switch / IPC", "They share data too easily", "They are less safe"], answer: 1, exp: "Processes give isolation at the cost of overhead; threads are lighter but share memory (and its risks)." },

  // ================= Threads (50) =================
  { id: "th-01", topic: "os-threads", q: "A thread is:", options: ["A separate program", "The smallest unit of CPU scheduling; a lightweight execution stream within a process", "A type of process", "A CPU core"], answer: 1, exp: "Threads of one process share code, data and open files but each has its own stack, registers and PC." },
  { id: "th-02", topic: "os-threads", q: "Threads of the same process SHARE:", options: ["Stack and registers", "Code (text), global/heap data, open files and signals", "The program counter", "Nothing"], answer: 1, exp: "Each thread has a private stack, register set and PC; everything else is shared." },
  { id: "th-03", topic: "os-threads", q: "The main advantage of threads over processes is:", options: ["Better isolation", "Lower creation and context-switch cost, and easy data sharing (no IPC needed)", "They cannot crash", "They use more memory"], answer: 1, exp: "No address-space switch is needed between threads of the same process." },
  { id: "th-04", topic: "os-threads", q: "The main danger of threads is:", options: ["They are slow", "Shared mutable data leads to race conditions without proper synchronization", "They cannot be scheduled", "They need a separate PID"], answer: 1, exp: "A bug in one thread can corrupt shared state and crash the whole process." },
  { id: "th-05", topic: "os-threads", q: "User-level threads are:", options: ["Managed by the kernel", "Managed by a user-space thread library; the kernel sees only one process", "Always faster in every case", "Unable to share data"], answer: 1, exp: "Fast to create/switch, but one blocking system call blocks all of them, and they cannot use multiple cores." },
  { id: "th-06", topic: "os-threads", q: "Kernel-level threads are:", options: ["Invisible to the OS", "Scheduled by the OS kernel; can run on different cores and a blocking call blocks only that thread", "Faster to create than user threads", "Not preemptible"], answer: 1, exp: "More overhead per operation but true parallelism and independent blocking." },
  { id: "th-07", topic: "os-threads", q: "The many-to-one threading model:", options: ["Maps many user threads to one kernel thread — no true parallelism, blocking blocks all", "Maps one user thread to many kernel threads", "Is the same as one-to-one", "Is used by Linux"], answer: 0, exp: "Simple but cannot exploit multiprocessors." },
  { id: "th-08", topic: "os-threads", q: "The one-to-one threading model (used by Linux, Windows):", options: ["Each user thread maps to a kernel thread — real parallelism, but thread creation has kernel overhead", "Many user threads share one kernel thread", "Has no kernel threads", "Cannot block"], answer: 0, exp: "The dominant modern model." },
  { id: "th-09", topic: "os-threads", q: "A race condition occurs when:", options: ["Two threads run on the same core", "The result depends on the non-deterministic timing/interleaving of threads accessing shared data", "A thread runs too fast", "There is only one thread"], answer: 1, exp: "The classic example: two threads doing count++ (read-modify-write) can lose an update." },
  { id: "th-10", topic: "os-threads", q: "A critical section is:", options: ["The most important code", "A code region that accesses shared resources and must not be executed by more than one thread at a time", "The kernel", "The main() function"], answer: 1, exp: "Mutual exclusion protects it (locks, semaphores, monitors)." },
  { id: "th-11", topic: "os-threads", q: "A mutex (mutual exclusion lock):", options: ["Allows many threads in the critical section", "Allows exactly one thread to hold it; others block until it is released", "Is the same as a semaphore initialized to N", "Never blocks"], answer: 1, exp: "It has ownership — only the locking thread should unlock it." },
  { id: "th-12", topic: "os-threads", q: "Thread-local storage (TLS) provides:", options: ["Shared global variables", "Per-thread private copies of a variable, avoiding the need to synchronize access", "Faster locks", "A thread's stack"], answer: 1, exp: "Each thread sees its own value (e.g. errno)." },
  { id: "th-13", topic: "os-threads", q: "The main thread of a process:", options: ["Is special and cannot be scheduled", "Is the initial thread created when the process starts; if it returns, the process usually exits", "Has no stack", "Cannot create other threads"], answer: 1, exp: "Other threads are spawned from it (or from each other)." },
  { id: "th-14", topic: "os-threads", q: "A thread pool is used to:", options: ["Store thread stacks", "Reuse a fixed set of worker threads for many tasks, avoiding per-task creation cost", "Limit memory", "Prevent deadlock"], answer: 1, exp: "Tasks are queued and picked up by idle workers." },
  { id: "th-15", topic: "os-threads", q: "Which is TRUE about a thread's stack?", options: ["All threads share one stack", "Each thread has its own stack for local variables and call frames", "The stack is in the kernel", "Threads have no stack"], answer: 1, exp: "Stack size is fixed at creation (default often ~1-8 MB)." },
  { id: "th-16", topic: "os-threads", q: "pthread_join():", options: ["Creates a thread", "Blocks the caller until the target thread terminates, optionally retrieving its return value", "Detaches a thread", "Sends a signal"], answer: 1, exp: "Analogous to wait() for processes; a detached thread cannot be joined." },
  { id: "th-17", topic: "os-threads", q: "A detached thread:", options: ["Cannot run", "Releases its resources automatically on exit and cannot be joined", "Runs in the kernel", "Shares no memory"], answer: 1, exp: "Use it for fire-and-forget background work." },
  { id: "th-18", topic: "os-threads", q: "Context switching between two threads of the SAME process is cheaper than between processes because:", options: ["Threads are smaller programs", "No address-space switch (page table / TLB flush) is needed", "Threads have no registers", "It is done in hardware"], answer: 1, exp: "The MMU context and cache stay warm." },
  { id: "th-19", topic: "os-threads", q: "A reentrant (thread-safe) function:", options: ["Can be called recursively only", "Can be safely executed concurrently by multiple threads (no shared mutable static state, or it is synchronized)", "Is always faster", "Uses no stack"], answer: 1, exp: "strtok() is not reentrant; strtok_r() is." },
  { id: "th-20", topic: "os-threads", q: "The GIL (Global Interpreter Lock) in CPython:", options: ["Speeds up threads", "Allows only one thread to execute Python bytecode at a time, limiting CPU-bound multithreading", "Prevents deadlock", "Is a hardware feature"], answer: 1, exp: "I/O-bound threads still benefit; CPU-bound work needs multiprocessing or a GIL-free build." },
  { id: "th-21", topic: "os-threads", q: "Which of these is per-thread, not shared?", options: ["Heap memory", "Global variables", "The register set and program counter", "Open file descriptors"], answer: 2, exp: "Registers, PC and stack are the thread's private execution context." },
  { id: "th-22", topic: "os-threads", q: "A condition variable is used with a mutex to:", options: ["Speed up the CPU", "Let a thread wait efficiently until some condition becomes true, releasing the mutex while waiting", "Prevent all context switches", "Allocate memory"], answer: 1, exp: "wait() atomically unlocks and sleeps; signal()/broadcast() wake waiters." },
  { id: "th-23", topic: "os-threads", q: "A spurious wakeup means:", options: ["The CPU wakes up randomly", "A thread waiting on a condition variable returns from wait() without being signalled — hence always re-check the condition in a loop", "A thread never wakes", "The mutex is corrupted"], answer: 1, exp: "'while (!condition) cond.wait(lock);' not 'if'." },
  { id: "th-24", topic: "os-threads", q: "Green threads / fibers / coroutines are:", options: ["Kernel threads", "User-space cooperatively-scheduled execution units, cheaper than OS threads", "Hardware threads", "Processes"], answer: 1, exp: "They yield control explicitly; used for high-concurrency I/O (Go goroutines, async/await)." },
  { id: "th-25", topic: "os-threads", q: "The classic increment race: two threads each do 'x = x + 1' 1,000,000 times starting from 0. The final value:", options: ["Is always 2,000,000", "Can be anything from ~1,000,000 to 2,000,000 due to lost updates", "Is always 1,000,000", "Is always 0"], answer: 1, exp: "The read-modify-write is not atomic; interleavings lose increments." },
  { id: "th-26", topic: "os-threads", q: "An atomic operation:", options: ["Uses atomic energy", "Completes as an indivisible unit — no other thread can observe an intermediate state", "Is always slow", "Requires a mutex"], answer: 1, exp: "Hardware provides atomic instructions (compare-and-swap, fetch-and-add)." },
  { id: "th-27", topic: "os-threads", q: "Compare-and-swap (CAS) is the basis of:", options: ["Page replacement", "Lock-free data structures and many synchronization primitives", "Disk scheduling", "Branch prediction"], answer: 1, exp: "CAS(addr, expected, new): atomically set *addr = new if *addr == expected." },
  { id: "th-28", topic: "os-threads", q: "Which is TRUE about multithreading on a single-core CPU?", options: ["It gives no benefit at all", "It still helps I/O-bound programs (overlap waiting with computation) via concurrency, but not CPU-bound ones (no parallelism)", "It doubles CPU speed", "It causes deadlock always"], answer: 1, exp: "Concurrency != parallelism." },
  { id: "th-29", topic: "os-threads", q: "The producer-consumer problem with a bounded buffer needs:", options: ["One mutex only", "A mutex for the buffer plus two counting semaphores (empty slots, full slots)", "No synchronization", "Two mutexes only"], answer: 1, exp: "Semaphores block the producer when full and the consumer when empty." },
  { id: "th-30", topic: "os-threads", q: "Thread cancellation with 'deferred' semantics means:", options: ["The thread stops immediately", "The target thread terminates only when it reaches a cancellation point, allowing cleanup", "Cancellation is ignored", "The process exits"], answer: 1, exp: "Asynchronous cancellation (stop anywhere) risks leaving locks held / resources leaked." },
  { id: "th-31", topic: "os-threads", q: "A memory barrier / fence:", options: ["Blocks memory access", "Enforces ordering of memory operations, preventing the CPU/compiler from reordering across it", "Allocates a page", "Is a type of lock"], answer: 1, exp: "Needed for correct lock-free code on weakly-ordered architectures." },
  { id: "th-32", topic: "os-threads", q: "False sharing occurs when:", options: ["Two threads share a variable correctly", "Two threads modify different variables that happen to lie on the same cache line, causing coherence traffic", "A lock is shared", "A file is shared"], answer: 1, exp: "Pad or align data to separate cache lines to avoid it." },
  { id: "th-33", topic: "os-threads", q: "Which is TRUE of thread priorities?", options: ["They guarantee execution order", "They are hints to the scheduler; over-reliance can cause priority inversion or starvation", "All threads have the same priority always", "Priority is set by the CPU"], answer: 1, exp: "Priority inheritance protocols mitigate priority inversion." },
  { id: "th-34", topic: "os-threads", q: "Priority inversion is:", options: ["A scheduling bug where a high-priority thread waits on a lock held by a low-priority thread that is itself preempted by a medium-priority thread", "When priorities are reversed by the OS", "A deadlock", "Normal behavior"], answer: 0, exp: "Famously affected the Mars Pathfinder; fixed with priority inheritance." },
  { id: "th-35", topic: "os-threads", q: "The number of threads that can run truly in parallel is bounded by:", options: ["The amount of RAM", "The number of CPU cores / hardware threads", "The stack size", "The number of processes"], answer: 1, exp: "More software threads than cores means time-slicing (concurrency, not parallelism)." },
  { id: "th-36", topic: "os-threads", q: "A read-write lock (shared-exclusive lock) allows:", options: ["Only one reader or writer at a time", "Multiple concurrent readers OR one exclusive writer", "Unlimited writers", "No readers"], answer: 1, exp: "Good for read-heavy workloads; can starve writers without a fairness policy." },
  { id: "th-37", topic: "os-threads", q: "The 'thundering herd' problem is:", options: ["Too many processes", "Many threads waking at once to contend for one resource, most going back to sleep — wasted work", "A stampede of interrupts", "A memory leak"], answer: 1, exp: "cond.signal() (wake one) is preferable to broadcast() when only one waiter can proceed." },
  { id: "th-38", topic: "os-threads", q: "Which is a correct statement about volatile in Java / C11 atomics?", options: ["It makes operations atomic and fast", "It ensures visibility/ordering of a variable across threads but does NOT make compound operations (x++) atomic", "It is only for hardware registers", "It disables threading"], answer: 1, exp: "Java volatile != atomic; use AtomicInteger or synchronized for x++." },
  { id: "th-39", topic: "os-threads", q: "A barrier (in parallel programming) makes:", options: ["One thread stop forever", "All participating threads wait until every thread has reached the barrier, then all proceed", "The CPU halt", "A critical section"], answer: 1, exp: "Used to synchronize phases of a parallel computation." },
  { id: "th-40", topic: "os-threads", q: "Which task is best done with multiprocessing rather than multithreading?", options: ["Overlapping network I/O", "A CPU-bound computation in a language with a global interpreter lock", "Updating a shared counter", "Sharing a large in-memory cache"], answer: 1, exp: "Separate processes bypass the GIL and use multiple cores." },
  { id: "th-41", topic: "os-threads", q: "Thread safety of a data structure means:", options: ["It cannot be modified", "Concurrent operations from multiple threads leave it in a consistent state without external locking", "It is immutable", "It uses no memory"], answer: 1, exp: "Achieved by internal locking, lock-free algorithms, or immutability." },
  { id: "th-42", topic: "os-threads", q: "Which is per-thread in most OSes?", options: ["The process's PID", "The thread ID (TID) and signal mask", "The heap", "The file descriptor table"], answer: 1, exp: "Each thread has its own TID, stack, register state and signal mask." },
  { id: "th-43", topic: "os-threads", q: "An I/O-bound server handling 10,000 connections is often best built with:", options: ["10,000 OS threads", "An event loop / async I/O with a small thread pool, or lightweight coroutines", "One thread doing blocking reads", "10,000 processes"], answer: 1, exp: "The C10k problem: thread-per-connection does not scale; use epoll/kqueue/io_uring." },
  { id: "th-44", topic: "os-threads", q: "When a multithreaded process forks, in the child:", options: ["All threads are duplicated", "Only the calling thread exists; locks held by other threads may be left in an inconsistent state", "The child has no threads", "Threads keep running"], answer: 1, exp: "This is why fork() in a threaded program should be followed immediately by exec()." },
  { id: "th-45", topic: "os-threads", q: "Lock contention increases with:", options: ["Fewer threads", "More threads trying to acquire the same lock, and longer critical sections", "Smaller data", "More cores only"], answer: 1, exp: "Reduce it with finer-grained locks, lock-free structures, or less shared state." },
  { id: "th-46", topic: "os-threads", q: "A 'daemon thread' (Java) is:", options: ["A malicious thread", "A background thread that does not prevent the JVM from exiting when all non-daemon threads finish", "A kernel thread", "The main thread"], answer: 1, exp: "Used for housekeeping like garbage collection." },
  { id: "th-47", topic: "os-threads", q: "The two-to-one... actually the many-to-many threading model:", options: ["Maps M user threads onto N <= M kernel threads, combining flexibility and parallelism", "Is the same as one-to-one", "Has no kernel threads", "Is unused"], answer: 0, exp: "Complex to implement; largely abandoned in favor of one-to-one plus user-space schedulers." },
  { id: "th-48", topic: "os-threads", q: "Which is TRUE: creating a thread vs creating a process:", options: ["Process creation is faster", "Thread creation is much faster (no address-space setup) and uses far less memory", "They cost the same", "Threads cannot be created at runtime"], answer: 1, exp: "This is why thread pools and lightweight tasks are common." },
  { id: "th-49", topic: "os-threads", q: "A worker thread that never blocks and busy-waits on a flag:", options: ["Is efficient", "Wastes a whole core spinning; a short spin then a blocking wait (adaptive) is better", "Cannot be scheduled", "Is required by the OS"], answer: 1, exp: "Spinlocks are only appropriate for very short critical sections on multiprocessors." },
  { id: "th-50", topic: "os-threads", q: "Amdahl's law applied to threading says:", options: ["More threads always means proportional speedup", "Speedup is capped by the serial fraction; synchronization and contention add further overhead", "Threads have no overhead", "10 threads = 10x speedup"], answer: 1, exp: "Real speedup also suffers from lock contention, false sharing and scheduling costs." },

  // ================= Inter-process Communication (50) =================
  { id: "ipc-01", topic: "os-ipc", q: "IPC is needed because:", options: ["Processes share memory by default", "Processes have separate address spaces and cannot directly access each other's memory", "Threads cannot communicate", "The CPU is slow"], answer: 1, exp: "The OS must mediate any data exchange between isolated processes." },
  { id: "ipc-02", topic: "os-ipc", q: "The two fundamental IPC models are:", options: ["Files and pipes", "Shared memory and message passing", "Signals and sockets", "Threads and processes"], answer: 1, exp: "Shared memory: fast, needs synchronization. Message passing: safer, kernel-mediated, higher overhead." },
  { id: "ipc-03", topic: "os-ipc", q: "Shared-memory IPC is fast because:", options: ["The kernel copies data twice", "After setup, processes read/write a common memory region directly with no kernel involvement per access", "It uses the network", "It compresses data"], answer: 1, exp: "Only the initial map is a system call; the tradeoff is that you must synchronize access yourself." },
  { id: "ipc-04", topic: "os-ipc", q: "A pipe provides:", options: ["Random access", "A unidirectional byte stream between two related processes (write end / read end)", "Shared memory", "A message queue with priorities"], answer: 1, exp: "Anonymous pipes connect a parent and child (e.g. 'ls | grep')." },
  { id: "ipc-05", topic: "os-ipc", q: "A named pipe (FIFO) differs from an anonymous pipe in that:", options: ["It is bidirectional", "It has a name in the filesystem, so unrelated processes can use it", "It is faster", "It uses TCP"], answer: 1, exp: "Created with mkfifo; still a unidirectional byte stream." },
  { id: "ipc-06", topic: "os-ipc", q: "A message queue (System V / POSIX):", options: ["Is a byte stream", "Lets processes exchange discrete, typed/prioritized messages that the kernel buffers", "Requires shared memory", "Cannot persist"], answer: 1, exp: "Messages retain boundaries and can be read out of order by type/priority." },
  { id: "ipc-07", topic: "os-ipc", q: "A Unix domain socket:", options: ["Only works over the network", "Provides bidirectional IPC between processes on the same machine, with a socket API and optional datagram/stream semantics", "Is slower than TCP loopback", "Cannot pass file descriptors"], answer: 1, exp: "It can also pass open file descriptors and credentials between processes." },
  { id: "ipc-08", topic: "os-ipc", q: "Signals as an IPC mechanism are:", options: ["High-bandwidth data channels", "Low-information asynchronous notifications (which signal was sent); good for control, not data", "Synchronous only", "Reliable and queued by default"], answer: 1, exp: "Standard signals are not queued; real-time signals (SIGRTMIN..) are queued and can carry a small value." },
  { id: "ipc-09", topic: "os-ipc", q: "In message passing, a 'blocking send' (synchronous):", options: ["Returns immediately", "Blocks the sender until the message is received (or delivered to the kernel buffer)", "Never blocks", "Drops the message"], answer: 1, exp: "Non-blocking send returns immediately; the pairing of send/receive blocking modes defines the rendezvous behavior." },
  { id: "ipc-10", topic: "os-ipc", q: "Direct vs indirect message passing: indirect communication uses:", options: ["The recipient's PID directly", "A mailbox / port that both processes reference", "Shared memory", "A pipe"], answer: 1, exp: "A mailbox decouples sender and receiver identities and can be shared by many." },
  { id: "ipc-11", topic: "os-ipc", q: "Which IPC mechanism is best for a request/response RPC between machines?", options: ["Shared memory", "Sockets (TCP/UDP)", "Anonymous pipes", "Signals"], answer: 1, exp: "Only network sockets (or higher-level RPC frameworks over them) cross machine boundaries." },
  { id: "ipc-12", topic: "os-ipc", q: "The producer-consumer buffer in shared memory needs synchronization because:", options: ["The buffer is too small", "Producer and consumer can access the shared indices/data concurrently, risking races", "Shared memory is slow", "The kernel forbids it"], answer: 1, exp: "Use semaphores or a mutex + condition variables placed in the shared region." },
  { id: "ipc-13", topic: "os-ipc", q: "mmap() with MAP_SHARED can be used for IPC by:", options: ["Mapping the same file into multiple processes' address spaces", "Creating a pipe", "Sending signals", "Opening a socket"], answer: 0, exp: "Writes by one process are visible to the others (and optionally persisted to the file)." },
  { id: "ipc-14", topic: "os-ipc", q: "A key limitation of anonymous pipes is:", options: ["They are bidirectional", "They only connect processes with a common ancestor (created before fork)", "They are too fast", "They persist after both ends close"], answer: 1, exp: "Named pipes / sockets remove the relationship requirement." },
  { id: "ipc-15", topic: "os-ipc", q: "When the read end of a pipe is closed and a process writes to it:", options: ["The data is buffered", "The writer receives SIGPIPE (and write() returns EPIPE)", "Nothing happens", "The pipe reopens"], answer: 1, exp: "Ignoring SIGPIPE lets you handle EPIPE gracefully." },
  { id: "ipc-16", topic: "os-ipc", q: "When all write ends of a pipe are closed, a read() returns:", options: ["An error", "0 (end-of-file)", "The last byte forever", "SIGPIPE"], answer: 1, exp: "EOF signals the reader that no more data will come." },
  { id: "ipc-17", topic: "os-ipc", q: "Message passing is generally preferred over shared memory for:", options: ["Bulk data transfer on one machine", "Distributed systems and when isolation/simplicity matter more than raw speed", "Real-time low latency on one core", "Avoiding all kernel calls"], answer: 1, exp: "No shared state to corrupt; naturally extends across machines." },
  { id: "ipc-18", topic: "os-ipc", q: "A socket is identified by:", options: ["A filename", "An IP address + port number (+ protocol)", "A PID", "A signal number"], answer: 1, exp: "The 4-tuple (src IP, src port, dst IP, dst port) identifies a TCP connection." },
  { id: "ipc-19", topic: "os-ipc", q: "The kernel buffers pipe data; if the buffer is full, a write():", options: ["Fails immediately", "Blocks the writer until the reader consumes some data (for a blocking pipe)", "Discards old data", "Grows the buffer infinitely"], answer: 1, exp: "This provides natural flow control / back-pressure." },
  { id: "ipc-20", topic: "os-ipc", q: "D-Bus (Linux) is:", options: ["A hardware bus", "A higher-level message-bus IPC system for desktop services (method calls, signals, addressing)", "A CPU feature", "A file format"], answer: 1, exp: "It runs over Unix sockets and provides service discovery and typed messages." },
  { id: "ipc-21", topic: "os-ipc", q: "Remote Procedure Call (RPC) hides IPC by:", options: ["Using shared memory", "Making a network request look like a local function call (marshalling args, sending, unmarshalling the result)", "Sending signals", "Copying files"], answer: 1, exp: "Stubs/proxies on each side handle serialization and transport (gRPC, XML-RPC, etc.)." },
  { id: "ipc-22", topic: "os-ipc", q: "Marshalling (serialization) is:", options: ["Locking a resource", "Converting in-memory data structures into a byte stream for transmission or storage", "Scheduling processes", "Allocating memory"], answer: 1, exp: "Unmarshalling reconstructs the structure on the other side (handling endianness, pointers, etc.)." },
  { id: "ipc-23", topic: "os-ipc", q: "Shared memory in POSIX is created with:", options: ["pipe()", "shm_open() + mmap() (or shmget()/shmat() for System V)", "socket()", "signal()"], answer: 1, exp: "shm_open returns an fd naming the segment; mmap maps it." },
  { id: "ipc-24", topic: "os-ipc", q: "Which IPC has the LOWEST latency for large data on a single machine?", options: ["TCP loopback", "Shared memory (zero-copy after setup)", "A message queue", "A named pipe"], answer: 1, exp: "No copying through the kernel per access." },
  { id: "ipc-25", topic: "os-ipc", q: "A 'zero-copy' IPC technique:", options: ["Copies data twice for safety", "Avoids copying data between user and kernel buffers (e.g. sendfile, splice, shared memory)", "Deletes the data", "Uses compression"], answer: 1, exp: "Reduces CPU and memory bandwidth for high-throughput data movement." },
  { id: "ipc-26", topic: "os-ipc", q: "The classic client-server model over sockets: the server calls, in order:", options: ["connect, send, recv", "socket, bind, listen, accept", "socket, connect, close", "open, read, write"], answer: 1, exp: "The client does socket, connect, then send/recv." },
  { id: "ipc-27", topic: "os-ipc", q: "UDP-based IPC/messaging is:", options: ["Reliable and ordered", "Connectionless, unreliable, message-oriented (no delivery or ordering guarantee), low overhead", "Stream-oriented", "Slower than TCP"], answer: 1, exp: "Good for real-time / broadcast where occasional loss is acceptable." },
  { id: "ipc-28", topic: "os-ipc", q: "Which is TRUE about System V IPC objects (message queues, semaphores, shared memory)?", options: ["They are removed when the creating process exits", "They persist until explicitly removed (ipcrm) or the system reboots — kernel persistence", "They are per-thread", "They cannot be shared"], answer: 1, exp: "A common source of resource leaks; POSIX equivalents have clearer lifetimes." },
  { id: "ipc-29", topic: "os-ipc", q: "An eventfd / pipe 'self-pipe trick' is used to:", options: ["Speed up disk I/O", "Safely wake up an event loop (e.g. from a signal handler) by writing a byte", "Allocate memory", "Fork a process"], answer: 1, exp: "It converts an asynchronous event into a readable file descriptor the loop already watches." },
  { id: "ipc-30", topic: "os-ipc", q: "The main synchronization concern with shared-memory IPC that message passing avoids is:", options: ["Network latency", "Race conditions on the shared region (the programmer must add locks/semaphores)", "Serialization cost", "Firewall rules"], answer: 1, exp: "Message passing has synchronization built into send/receive." },
  { id: "ipc-31", topic: "os-ipc", q: "A mailbox owned by the OS (vs by a process) has the advantage that:", options: ["It is faster", "It persists independently of any single process and its access can be controlled", "It needs no memory", "Only one process can use it"], answer: 1, exp: "Process-owned mailboxes vanish when the owner exits." },
  { id: "ipc-32", topic: "os-ipc", q: "Passing a file descriptor between processes is possible via:", options: ["A regular pipe", "A Unix domain socket with SCM_RIGHTS ancillary data", "Shared memory", "A signal"], answer: 1, exp: "The kernel installs a new fd in the receiver referring to the same open file." },
  { id: "ipc-33", topic: "os-ipc", q: "The 'rendezvous' model of message passing means:", options: ["Both send and receive block until the other is ready (no buffering)", "Messages are always buffered", "The sender never blocks", "The receiver polls"], answer: 0, exp: "Ada's model; it needs no kernel buffer and synchronizes the two processes tightly." },
  { id: "ipc-34", topic: "os-ipc", q: "Which IPC is most appropriate for 'ls -l | wc -l'?", options: ["Shared memory", "An anonymous pipe (stdout of ls to stdin of wc)", "A socket", "A message queue"], answer: 1, exp: "The shell creates the pipe and forks both commands." },
  { id: "ipc-35", topic: "os-ipc", q: "The bounded-buffer capacity in message passing affects:", options: ["Correctness only", "How decoupled the sender and receiver can be — larger buffer tolerates bigger rate mismatches", "The message content", "The PID"], answer: 1, exp: "Zero-capacity = rendezvous; unbounded = sender never blocks (but memory can grow)." },
  { id: "ipc-36", topic: "os-ipc", q: "A key security benefit of message-passing IPC over shared memory:", options: ["It is faster", "The kernel can enforce access control and validate messages at the boundary", "It uses less memory", "It needs no permissions"], answer: 1, exp: "Shared memory exposes raw memory; a corrupt writer can crash readers." },
  { id: "ipc-37", topic: "os-ipc", q: "The 'C10k problem' relates IPC to:", options: ["10,000 pipes", "Scaling a server to 10,000+ concurrent socket connections efficiently (event-driven I/O)", "10 KB messages", "10,000 signals"], answer: 1, exp: "Solved with epoll/kqueue/io_uring instead of thread-per-connection." },
  { id: "ipc-38", topic: "os-ipc", q: "Sockets created with SOCK_STREAM provide:", options: ["Unreliable datagrams", "A reliable, ordered, connection-oriented byte stream (TCP)", "Broadcast", "Message boundaries"], answer: 1, exp: "SOCK_DGRAM gives connectionless datagrams (UDP)." },
  { id: "ipc-39", topic: "os-ipc", q: "The main drawback of signals for IPC is:", options: ["Too much data", "Very limited information, not queued (standard signals), and handlers run in a restricted async-signal-safe context", "They are slow", "They need root"], answer: 1, exp: "Only a fixed set of numbers; two identical pending signals may be merged." },
  { id: "ipc-40", topic: "os-ipc", q: "In a pub/sub messaging system, publishers and subscribers are:", options: ["Tightly coupled", "Decoupled — publishers send to a topic; subscribers receive from topics they subscribe to, not knowing each other", "The same process", "Always on one machine"], answer: 1, exp: "A broker (or the OS) routes messages by topic." },
  { id: "ipc-41", topic: "os-ipc", q: "Which IPC preserves message boundaries?", options: ["Byte-stream pipe", "TCP socket", "Message queue / UDP datagram socket", "Shared memory"], answer: 2, exp: "Stream IPC (pipes, TCP) delivers a byte stream; the app must frame messages itself." },
  { id: "ipc-42", topic: "os-ipc", q: "The 'splice' / 'tee' system calls (Linux) enable:", options: ["Process creation", "Moving data between file descriptors (e.g. pipe to socket) without copying to user space", "Signal handling", "Memory allocation"], answer: 1, exp: "A zero-copy path for proxying data." },
  { id: "ipc-43", topic: "os-ipc", q: "A semaphore used across processes must be:", options: ["A local variable", "Placed in shared memory (or be a named/kernel semaphore) so both processes reference the same object", "Copied to each process", "In a register"], answer: 1, exp: "POSIX sem_open (named) or sem_init with pshared=1 in a shared region." },
  { id: "ipc-44", topic: "os-ipc", q: "The typical latency ordering (fastest to slowest) for same-machine IPC:", options: ["network socket < pipe < shared memory", "shared memory < pipe/Unix socket < TCP loopback", "message queue < shared memory < signal", "signal < shared memory < pipe"], answer: 1, exp: "Shared memory avoids kernel copies; TCP adds protocol processing." },
  { id: "ipc-45", topic: "os-ipc", q: "A dead-letter queue in messaging holds:", options: ["The fastest messages", "Messages that could not be delivered or processed after retries", "Encrypted messages", "System messages"], answer: 1, exp: "It prevents poison messages from blocking a queue and allows later inspection." },
  { id: "ipc-46", topic: "os-ipc", q: "Which is TRUE about shared memory and CPU caches on a multicore system?", options: ["No coherence issues", "Cache-coherence protocols keep the shared region consistent, but heavy contention causes cache-line ping-pong (slow)", "Shared memory bypasses caches", "Each core has its own copy that never syncs"], answer: 1, exp: "Design shared structures to minimize cross-core write sharing." },
  { id: "ipc-47", topic: "os-ipc", q: "The clipboard on a desktop OS is implemented with:", options: ["A physical wire", "An OS-mediated IPC mechanism (e.g. X selections / Wayland / Windows clipboard API)", "A shared file only", "Signals"], answer: 1, exp: "Copy places data (or a promise) with the window server; paste requests it." },
  { id: "ipc-48", topic: "os-ipc", q: "For streaming a large log from one process to another on the same host with back-pressure, a good choice is:", options: ["Signals", "A pipe or Unix domain stream socket (blocking write provides flow control)", "Polling a shared counter", "UDP"], answer: 1, exp: "The full-buffer blocking behavior naturally throttles the producer." },
  { id: "ipc-49", topic: "os-ipc", q: "Message queues survive a consumer restart when:", options: ["The queue is process-owned", "The queue has kernel/broker persistence so undelivered messages remain", "The consumer was fast", "Never"], answer: 1, exp: "Durable queues (or kernel-persistent System V queues) buffer messages across restarts." },
  { id: "ipc-50", topic: "os-ipc", q: "The fundamental tradeoff between the two IPC models is:", options: ["Speed vs color", "Shared memory: fastest but you manage synchronization and it is single-machine; message passing: safer, distributable, but copying/kernel overhead", "There is no tradeoff", "Message passing is always better"], answer: 1, exp: "Choose based on data volume, machine boundaries, and how much shared state you can tolerate." },

  // ================= Concurrency & Synchronization (50) =================
  { id: "sy-01", topic: "os-sync", q: "The critical-section problem requires a solution to satisfy:", options: ["Speed, size, simplicity", "Mutual exclusion, progress, and bounded waiting", "Fairness only", "Determinism"], answer: 1, exp: "Mutual exclusion (one at a time), progress (no indefinite postponement if section is free), bounded waiting (no starvation)." },
  { id: "sy-02", topic: "os-sync", q: "A race condition arises when:", options: ["Two processes run on different CPUs", "The outcome depends on the interleaving order of concurrent accesses to shared data", "A process runs too slowly", "There is no shared data"], answer: 1, exp: "Synchronization removes the dependence on timing." },
  { id: "sy-03", topic: "os-sync", q: "A counting semaphore with value S:", options: ["Allows S threads through wait() before blocking; V() increments it", "Allows only 1 thread ever", "Is the same as a mutex", "Cannot go below 0"], answer: 0, exp: "wait/P decrements (blocks if < 0 after); signal/V increments (wakes a waiter)." },
  { id: "sy-04", topic: "os-sync", q: "A binary semaphore is often used as a:", options: ["Counter", "Lock (mutex), value 0 or 1", "Barrier", "Clock"], answer: 1, exp: "Unlike a mutex it has no ownership — any thread can signal it." },
  { id: "sy-05", topic: "os-sync", q: "Peterson's algorithm provides mutual exclusion for two processes using:", options: ["A hardware lock instruction", "Two shared boolean flags and a turn variable (software-only)", "A semaphore", "Disabling interrupts"], answer: 1, exp: "It satisfies all three requirements but assumes sequential consistency (needs memory fences on real CPUs)." },
  { id: "sy-06", topic: "os-sync", q: "Disabling interrupts to protect a critical section:", options: ["Works safely on multiprocessors", "Works on a single processor only; it does not stop other CPUs and can harm responsiveness", "Is the standard user-space technique", "Prevents all bugs"], answer: 1, exp: "Kernels use it briefly for very short critical sections on uniprocessors." },
  { id: "sy-07", topic: "os-sync", q: "Test-and-set and compare-and-swap are:", options: ["Scheduling algorithms", "Atomic hardware instructions used to build locks", "System calls", "Page-replacement policies"], answer: 1, exp: "They read-and-conditionally-modify a memory word in one indivisible step." },
  { id: "sy-08", topic: "os-sync", q: "A spinlock:", options: ["Puts the waiting thread to sleep", "Busy-waits (loops) until the lock is free — good only for very short holds on multiprocessors", "Is slower than a mutex always", "Cannot be implemented"], answer: 1, exp: "It avoids the context-switch cost but wastes CPU while spinning." },
  { id: "sy-09", topic: "os-sync", q: "A monitor is:", options: ["A display device", "A high-level synchronization construct: a module whose procedures execute with automatic mutual exclusion, plus condition variables", "A semaphore", "A scheduling policy"], answer: 1, exp: "Java's 'synchronized' and 'wait/notify' implement a monitor per object." },
  { id: "sy-10", topic: "os-sync", q: "In the bounded-buffer producer-consumer solution with semaphores, the semaphores are:", options: ["One mutex only", "mutex (=1), empty (=N), full (=0)", "Three mutexes", "Two turn variables"], answer: 1, exp: "Producer: wait(empty), wait(mutex), ... signal(mutex), signal(full). Consumer mirrors it." },
  { id: "sy-11", topic: "os-sync", q: "The readers-writers problem's key constraint is:", options: ["Only one reader at a time", "Multiple readers may read concurrently, but a writer needs exclusive access", "Writers can share", "No one can read"], answer: 1, exp: "Variants prioritize readers, writers, or fairness." },
  { id: "sy-12", topic: "os-sync", q: "Reader-priority in the readers-writers problem can cause:", options: ["Reader starvation", "Writer starvation (a stream of readers keeps the writer waiting forever)", "Deadlock", "Nothing"], answer: 1, exp: "Writer-priority or fair (FIFO) variants fix this." },
  { id: "sy-13", topic: "os-sync", q: "The dining philosophers problem illustrates:", options: ["Scheduling", "Deadlock and starvation in resource allocation among concurrent processes", "Paging", "File systems"], answer: 1, exp: "5 philosophers, 5 forks; each needs 2 adjacent forks to eat." },
  { id: "sy-14", topic: "os-sync", q: "One deadlock-free solution to dining philosophers is:", options: ["Everyone grabs the left fork first", "Break symmetry: e.g. odd philosophers pick left then right, even pick right then left (or allow at most 4 to sit)", "Add more philosophers", "Remove all forks"], answer: 1, exp: "Any technique that prevents a circular wait works." },
  { id: "sy-15", topic: "os-sync", q: "Busy waiting (spinning) is wasteful because:", options: ["It uses no CPU", "The waiting thread consumes CPU cycles doing nothing useful", "It causes deadlock", "It is illegal"], answer: 1, exp: "Blocking synchronization yields the CPU; a hybrid (spin briefly, then block) is common." },
  { id: "sy-16", topic: "os-sync", q: "A semaphore's wait() and signal() must be:", options: ["Called only by the main thread", "Atomic (indivisible) operations", "Slow", "Always paired in the same function"], answer: 1, exp: "Otherwise two threads could both pass a semaphore of value 1." },
  { id: "sy-17", topic: "os-sync", q: "Which is TRUE about mutex vs binary semaphore?", options: ["They are identical", "A mutex has ownership (only the locker unlocks) and often supports priority inheritance; a semaphore does not", "A semaphore is always faster", "A mutex allows many holders"], answer: 1, exp: "Use a mutex for locking, a semaphore for signaling / counting resources." },
  { id: "sy-18", topic: "os-sync", q: "A condition variable must be used together with:", options: ["Another condition variable", "A mutex (to protect the shared predicate and make wait/signal race-free)", "A semaphore", "A spinlock only"], answer: 1, exp: "wait() atomically releases the mutex and sleeps, reacquiring it on wakeup." },
  { id: "sy-19", topic: "os-sync", q: "The 'lost wakeup' problem happens when:", options: ["A signal is sent before the thread starts waiting, and is missed", "The CPU loses power", "Two threads wake at once", "A mutex is unlocked twice"], answer: 0, exp: "Holding the mutex while checking the predicate and calling wait() prevents it." },
  { id: "sy-20", topic: "os-sync", q: "A barrier synchronization primitive:", options: ["Blocks one thread", "Makes all N threads wait until all have arrived, then releases them together", "Is a mutex", "Prevents context switches"], answer: 1, exp: "Used between phases of a parallel algorithm." },
  { id: "sy-21", topic: "os-sync", q: "Lock-free (non-blocking) algorithms guarantee:", options: ["No thread ever waits", "System-wide progress — some thread always makes progress, even if others are delayed/suspended", "Wait-freedom", "No memory use"], answer: 1, exp: "Wait-free is stronger: EVERY thread makes progress in bounded steps." },
  { id: "sy-22", topic: "os-sync", q: "The ABA problem in lock-free programming is:", options: ["A naming issue", "A CAS succeeds because a value changed from A to B and back to A, hiding an intervening modification", "A type of deadlock", "A scheduling anomaly"], answer: 1, exp: "Solved with tagged pointers / version counters or hazard pointers." },
  { id: "sy-23", topic: "os-sync", q: "Coarse-grained locking (one big lock):", options: ["Maximizes parallelism", "Is simple and correct but serializes access, limiting scalability", "Prevents deadlock always", "Uses no memory"], answer: 1, exp: "Fine-grained locking improves concurrency but risks deadlock and adds overhead." },
  { id: "sy-24", topic: "os-sync", q: "Which correctly orders acquiring two locks to avoid deadlock?", options: ["Each thread grabs them in a different order", "All threads acquire locks in the same global order", "Randomly", "Grab both with no order"], answer: 1, exp: "A consistent lock ordering breaks the circular-wait condition." },
  { id: "sy-25", topic: "os-sync", q: "A recursive (reentrant) mutex:", options: ["Cannot be locked twice", "Can be locked multiple times by the SAME thread (with a matching number of unlocks)", "Is shared across processes", "Is lock-free"], answer: 1, exp: "Useful when a locked function calls another locked function on the same object." },
  { id: "sy-26", topic: "os-sync", q: "The volatile keyword in C:", options: ["Provides mutual exclusion", "Prevents the compiler from caching/reordering a variable's accesses, but does NOT provide atomicity or cross-thread ordering (use atomics)", "Makes a variable thread-local", "Is a lock"], answer: 1, exp: "It is for memory-mapped I/O and signal handlers, not thread synchronization." },
  { id: "sy-27", topic: "os-sync", q: "A futex (fast userspace mutex, Linux) works by:", options: ["Always calling the kernel", "Handling the uncontended case entirely in user space with an atomic op, only calling the kernel to block/wake on contention", "Disabling interrupts", "Spinning forever"], answer: 1, exp: "This makes uncontended lock/unlock very cheap." },
  { id: "sy-28", topic: "os-sync", q: "In the producer-consumer problem, if wait(mutex) is done BEFORE wait(empty) by the producer:", options: ["It is more efficient", "Deadlock can occur: producer holds mutex, buffer full, consumer needs mutex to make room", "Nothing changes", "Starvation only"], answer: 1, exp: "Resource semaphores (empty/full) must be acquired before the mutex." },
  { id: "sy-29", topic: "os-sync", q: "Sequential consistency means:", options: ["Instructions run in source order per thread and there is one global interleaving all threads agree on", "No reordering ever", "Locks are unnecessary", "Only one thread runs"], answer: 0, exp: "Real hardware provides weaker models; fences/atomics restore the needed ordering." },
  { id: "sy-30", topic: "os-sync", q: "Optimistic concurrency control (in software / databases):", options: ["Locks everything up front", "Proceeds without locking and validates at commit, retrying on conflict — good when conflicts are rare", "Is the same as pessimistic locking", "Never fails"], answer: 1, exp: "Transactional memory and CAS loops are examples." },
  { id: "sy-31", topic: "os-sync", q: "A semaphore initialized to 0 is typically used for:", options: ["Mutual exclusion", "Signaling — one thread waits, another signals when an event occurs", "Counting free slots", "Nothing useful"], answer: 1, exp: "e.g. thread A does work then signal(s); thread B does wait(s) to proceed after A." },
  { id: "sy-32", topic: "os-sync", q: "Which is NOT a valid solution to the critical-section problem on a multiprocessor?", options: ["Peterson's algorithm (with fences)", "Disabling local interrupts", "A spinlock built on test-and-set", "A mutex"], answer: 1, exp: "Disabling interrupts on one core does not stop other cores from entering the section." },
  { id: "sy-33", topic: "os-sync", q: "Priority inheritance solves priority inversion by:", options: ["Boosting the low-priority lock holder to the highest priority of any thread waiting for that lock", "Lowering all priorities", "Disabling scheduling", "Aborting the low-priority thread"], answer: 0, exp: "The holder finishes quickly and releases the lock." },
  { id: "sy-34", topic: "os-sync", q: "The 'signal and continue' vs 'signal and wait' monitor semantics differ in:", options: ["Whether the signalling thread keeps the monitor lock or hands it to the woken thread", "The number of condition variables", "Lock ownership rules", "Nothing"], answer: 0, exp: "Java uses signal-and-continue, which is why waiters must re-check the predicate in a loop." },
  { id: "sy-35", topic: "os-sync", q: "An RCU (Read-Copy-Update) mechanism (Linux kernel) allows:", options: ["Writers to block readers", "Readers to proceed with almost zero overhead while writers make a copy and swap it in, deferring reclamation until all readers finish", "Only one reader", "No writers"], answer: 1, exp: "Extremely read-scalable; used for kernel data structures." },
  { id: "sy-36", topic: "os-sync", q: "Which pattern reduces lock contention on a shared counter?", options: ["A single global lock", "Per-thread (sharded) counters summed on read", "A spinlock", "Disabling interrupts"], answer: 1, exp: "Threads increment their own counter; readers aggregate. Trades read cost for write scalability." },
  { id: "sy-37", topic: "os-sync", q: "A deadlock among two threads each holding one lock and waiting for the other's is broken by:", options: ["Adding a third lock", "trylock with backoff, a global lock order, or timeout-and-retry", "Spinning harder", "Raising priority"], answer: 1, exp: "trylock: if you cannot get the second lock, release the first and retry." },
  { id: "sy-38", topic: "os-sync", q: "The 'test and test-and-set' spinlock optimization:", options: ["Uses two atomic ops", "First spins on a plain read (cache-local) and only does the expensive atomic test-and-set when the lock looks free", "Is slower", "Disables the cache"], answer: 1, exp: "It reduces cache-coherence bus traffic while spinning." },
  { id: "sy-39", topic: "os-sync", q: "Amdahl's law implies that adding threads to a program with a large critical section:", options: ["Always scales linearly", "Yields diminishing returns because the serialized critical section becomes the bottleneck", "Removes the need for locks", "Speeds up the critical section"], answer: 1, exp: "Shrink the critical section or make it lock-free to scale." },
  { id: "sy-40", topic: "os-sync", q: "A 'happens-before' relationship in a memory model establishes:", options: ["Thread priority", "That the effects of one operation are visible to another (via program order, locks, or atomics with the right ordering)", "Scheduling order", "Deadlock freedom"], answer: 1, exp: "Data-race-free programs behave sequentially consistently under most models." },
  { id: "sy-41", topic: "os-sync", q: "Which is TRUE about semaphores and deadlock?", options: ["Semaphores cannot cause deadlock", "Misusing semaphores (wrong acquire order, forgetting a signal) can cause deadlock or starvation", "Semaphores prevent all deadlock", "Only mutexes deadlock"], answer: 1, exp: "A forgotten signal() blocks all future waiters permanently." },
  { id: "sy-42", topic: "os-sync", q: "The sleeping-barber problem models:", options: ["CPU idle time", "A server (barber) with a waiting room of limited capacity, using semaphores for customers/barber/mutex", "Disk scheduling", "Page faults"], answer: 1, exp: "Another classic synchronization exercise like producer-consumer and readers-writers." },
  { id: "sy-43", topic: "os-sync", q: "A 'benign' data race (e.g. a stats counter that can be slightly off) is still problematic because:", options: ["It always crashes", "Under the C/C++ memory model any data race is undefined behavior; the compiler may miscompile", "It is slow", "It uses more memory"], answer: 1, exp: "Use relaxed atomics even for 'unimportant' shared variables." },
  { id: "sy-44", topic: "os-sync", q: "Which synchronization primitive is best for 'wait until this one-time initialization is done'?", options: ["A spinlock", "std::call_once / pthread_once (or a double-checked lock with atomics)", "A barrier", "A counting semaphore of N"], answer: 1, exp: "It ensures the initializer runs exactly once even with concurrent first callers." },
  { id: "sy-45", topic: "os-sync", q: "Transactional memory lets a block of code:", options: ["Run without any isolation", "Execute atomically and in isolation; on a conflict it aborts and retries (like a database transaction)", "Skip synchronization forever", "Only run once"], answer: 1, exp: "Hardware TM (Intel TSX) and software TM implement this; composability is the big win over locks." },
  { id: "sy-46", topic: "os-sync", q: "A counting semaphore initialized to N limits:", options: ["The number of threads to N total", "The number of threads concurrently using a pool of N identical resources", "The buffer size", "The priority"], answer: 1, exp: "e.g. N database connections: wait() to borrow, signal() to return." },
  { id: "sy-47", topic: "os-sync", q: "The main correctness rule when using a condition variable:", options: ["Call signal before wait", "Always re-check the predicate in a while loop after wait() returns (spurious wakeups, signal-and-continue)", "Never hold the mutex", "Use two mutexes"], answer: 1, exp: "'if' is a classic bug; 'while' is correct." },
  { id: "sy-48", topic: "os-sync", q: "Which is TRUE about spinlocks in user space on a single-core machine?", options: ["They are ideal", "They are almost always wrong — the spinner cannot make progress until it is preempted, wasting its whole quantum", "They are faster than mutexes", "They prevent context switches usefully"], answer: 1, exp: "Spinlocks make sense mainly in kernels / multiprocessors for tiny critical sections." },
  { id: "sy-49", topic: "os-sync", q: "The 'double-checked locking' pattern (pre-C++11) was broken because:", options: ["It used too many locks", "Without proper memory ordering, another thread could see a non-null pointer to a partially constructed object", "It was too slow", "It deadlocked"], answer: 1, exp: "Fixed with acquire/release atomics or a proper once-init primitive." },
  { id: "sy-50", topic: "os-sync", q: "Overall, the goal of synchronization is to:", options: ["Make programs single-threaded", "Coordinate concurrent access to shared resources so the result is correct (as if some valid serial order occurred) without unnecessarily limiting parallelism", "Slow down fast threads", "Remove all shared data"], answer: 1, exp: "Correctness first, then maximize concurrency." },

  // ================= Deadlock (50) =================
  { id: "dl-01", topic: "os-deadlock", q: "The four necessary (Coffman) conditions for deadlock are:", options: ["Preemption, sharing, ordering, waiting", "Mutual exclusion, hold-and-wait, no preemption, circular wait", "Starvation, aging, priority, quantum", "Fetch, decode, execute, stall"], answer: 1, exp: "All four must hold simultaneously; breaking any one prevents deadlock." },
  { id: "dl-02", topic: "os-deadlock", q: "Deadlock differs from starvation in that:", options: ["They are the same", "In deadlock a set of processes are all permanently blocked waiting on each other; in starvation a process is indefinitely delayed but the system makes progress", "Starvation is worse", "Deadlock resolves itself"], answer: 1, exp: "Starvation can end (e.g. via aging); deadlock cannot without intervention." },
  { id: "dl-03", topic: "os-deadlock", q: "'Hold and wait' means a process:", options: ["Holds no resources", "Holds at least one resource while waiting to acquire additional ones held by others", "Never waits", "Releases all resources before waiting"], answer: 1, exp: "Requiring all resources to be requested at once breaks this condition." },
  { id: "dl-04", topic: "os-deadlock", q: "'Circular wait' means:", options: ["A process waits for itself", "There is a cycle P0 -> P1 -> ... -> Pn -> P0 where each waits for a resource the next holds", "All processes wait for the CPU", "Resources are circular"], answer: 1, exp: "Imposing a total ordering on resource types and requesting in order breaks it." },
  { id: "dl-05", topic: "os-deadlock", q: "In a resource-allocation graph with only single-instance resources, a cycle means:", options: ["Nothing", "Deadlock", "Starvation", "High CPU"], answer: 1, exp: "With multiple instances per resource type, a cycle is necessary but not sufficient for deadlock." },
  { id: "dl-06", topic: "os-deadlock", q: "The three strategies for handling deadlock are:", options: ["Prevention, avoidance, detection & recovery (and 'ignore it' — the ostrich algorithm)", "Fetch, decode, execute", "Paging, swapping, segmentation", "FCFS, SJF, RR"], answer: 0, exp: "Most general-purpose OSes use the ostrich approach and let the user reboot / kill." },
  { id: "dl-07", topic: "os-deadlock", q: "Deadlock PREVENTION works by:", options: ["Predicting the future", "Structurally ensuring at least one Coffman condition can never hold", "Detecting cycles", "Rolling back transactions"], answer: 1, exp: "e.g. no hold-and-wait, or preemptible resources, or ordered requests." },
  { id: "dl-08", topic: "os-deadlock", q: "Deadlock AVOIDANCE (e.g. Banker's algorithm) requires:", options: ["No information", "Advance knowledge of the maximum resources each process may need", "A resource-allocation graph only", "Killing processes"], answer: 1, exp: "The system grants a request only if the resulting state is 'safe'." },
  { id: "dl-09", topic: "os-deadlock", q: "A 'safe state' means:", options: ["No process is running", "There exists an ordering of all processes such that each can obtain its maximum resources, run, and release — even if all request their max now", "The system is idle", "No resources are allocated"], answer: 1, exp: "A safe state is deadlock-free; an unsafe state MAY lead to deadlock." },
  { id: "dl-10", topic: "os-deadlock", q: "The Banker's algorithm's safety check computes:", options: ["Page faults", "Whether a safe sequence exists using Available, Max, Allocation and Need matrices", "CPU utilization", "The wait-for graph"], answer: 1, exp: "Need = Max - Allocation; find a process whose Need <= Work, add its Allocation to Work, repeat." },
  { id: "dl-11", topic: "os-deadlock", q: "Deadlock DETECTION uses a:", options: ["Banker's algorithm", "Wait-for graph (for single-instance resources) — a cycle indicates deadlock", "Page table", "Ready queue"], answer: 1, exp: "The wait-for graph is the resource-allocation graph with resource nodes collapsed." },
  { id: "dl-12", topic: "os-deadlock", q: "Recovery from deadlock can be done by:", options: ["Waiting longer", "Process termination (abort one or all in the cycle) or resource preemption (roll back a victim)", "Adding RAM", "Lowering priorities"], answer: 1, exp: "Choosing a victim minimizes cost (priority, progress made, resources held)." },
  { id: "dl-13", topic: "os-deadlock", q: "Requiring a process to request ALL its resources at once (before starting) prevents:", options: ["Circular wait", "Hold and wait", "Mutual exclusion", "No preemption"], answer: 1, exp: "Downside: low resource utilization and possible starvation." },
  { id: "dl-14", topic: "os-deadlock", q: "Making resources preemptible (take them from a waiting process) attacks which condition?", options: ["Mutual exclusion", "No preemption", "Circular wait", "Hold and wait"], answer: 1, exp: "Works for CPU registers/memory (save/restore state) but not for printers or locks mid-operation." },
  { id: "dl-15", topic: "os-deadlock", q: "Which Coffman condition is usually impossible to eliminate?", options: ["Mutual exclusion (some resources are inherently non-sharable, e.g. a printer, a mutex)", "Hold and wait", "No preemption", "Circular wait"], answer: 0, exp: "You cannot make a lock 'sharable' without defeating its purpose." },
  { id: "dl-16", topic: "os-deadlock", q: "In the Banker's algorithm, a request is granted only if:", options: ["The process has waited long enough", "Request <= Need, Request <= Available, AND the resulting state passes the safety check", "The process has the highest priority", "Available > 0"], answer: 1, exp: "Otherwise the process must wait even though resources are free." },
  { id: "dl-17", topic: "os-deadlock", q: "Deadlock avoidance is conservative: it may:", options: ["Grant unsafe requests", "Deny a request (make a process wait) even when granting it would NOT actually cause deadlock", "Cause deadlock", "Ignore the maximum claims"], answer: 1, exp: "It errs on the side of caution because it only knows worst-case maximums." },
  { id: "dl-18", topic: "os-deadlock", q: "The 'ostrich algorithm' means:", options: ["Detect and recover quickly", "Ignore the problem and assume deadlocks are rare enough to tolerate (used by Windows/Linux for user processes)", "Prevent deadlock structurally", "Run the Banker's algorithm"], answer: 1, exp: "Cheaper than the overhead of prevention/avoidance for infrequent deadlocks." },
  { id: "dl-19", topic: "os-deadlock", q: "A livelock is:", options: ["A deadlock that resolves", "Processes are not blocked but keep changing state in response to each other without making progress (e.g. two people stepping aside repeatedly)", "A lock that never releases", "Normal operation"], answer: 1, exp: "CPU is busy; no useful work. Randomized backoff usually breaks it." },
  { id: "dl-20", topic: "os-deadlock", q: "In a system with 3 identical resource units and 3 processes each needing at most 2, deadlock:", options: ["Is inevitable", "Is impossible (at least one process can always get its 2nd unit)", "Depends on scheduling", "Requires more units"], answer: 1, exp: "Sum of max needs (6) with a rule that no cycle can complete: with 3 units and each needing 2, if each holds 1 then 1 unit is free for one to finish. Actually: 3 units, each holds 1 => 0 free => none can get a 2nd. Wait — 3 units total, 3 processes hold 1 each = 3 used, 0 free => deadlock possible! The classic safe rule: if sum(max_i) < units + n then no deadlock; 6 < 3 + 3 = 6 is false, so deadlock IS possible here." },
  { id: "dl-21", topic: "os-deadlock", q: "The condition 'sum of maximum needs < (resources + number of processes)' guarantees:", options: ["Deadlock", "No deadlock (there is always a process that can complete)", "Starvation", "A safe state only sometimes"], answer: 1, exp: "A pigeonhole argument: some process can always acquire its remaining need." },
  { id: "dl-22", topic: "os-deadlock", q: "Deadlock detection frequency is a tradeoff:", options: ["Detect never", "Frequent detection catches deadlocks fast but costs CPU; infrequent detection lets resources sit idle longer", "It has no cost", "Always detect on every request"], answer: 1, exp: "A common heuristic: run detection when CPU utilization drops below a threshold." },
  { id: "dl-23", topic: "os-deadlock", q: "The wait-for graph is obtained from the resource-allocation graph by:", options: ["Adding resource nodes", "Removing resource nodes and adding an edge Pi -> Pj if Pi waits for a resource held by Pj", "Reversing all edges", "Deleting all edges"], answer: 1, exp: "A cycle in the wait-for graph (single-instance resources) = deadlock." },
  { id: "dl-24", topic: "os-deadlock", q: "Which real-world scenario is a classic deadlock?", options: ["A single-lane bridge with cars entering from both ends and meeting in the middle", "A queue at a bank", "A full parking lot", "A slow website"], answer: 0, exp: "Neither car can proceed or back up if others are behind; one side must yield (preemption/prevention)." },
  { id: "dl-25", topic: "os-deadlock", q: "Two threads: T1 locks A then B; T2 locks B then A. The fix is:", options: ["Add a third lock", "Make both acquire A before B (consistent global order)", "Use spinlocks", "Increase priorities"], answer: 1, exp: "Consistent ordering removes the circular-wait possibility." },
  { id: "dl-26", topic: "os-deadlock", q: "In deadlock recovery by rollback, a process is rolled back to a:", options: ["Random point", "Previously saved safe checkpoint, then restarted", "The very beginning always", "The deadlock point"], answer: 1, exp: "Checkpointing periodically limits how much work is lost." },
  { id: "dl-27", topic: "os-deadlock", q: "Choosing a deadlock victim considers:", options: ["Only the PID", "Priority, how long it has run, resources held, resources needed to finish, and how many rollbacks it has suffered (to avoid always picking the same one)", "Alphabetical order", "Memory address"], answer: 1, exp: "Minimizing total cost while avoiding starvation of the victim." },
  { id: "dl-28", topic: "os-deadlock", q: "Database systems typically handle deadlock by:", options: ["Prevention via Banker's algorithm", "Detection (wait-for graph or timeout) and aborting one transaction (the victim)", "Ignoring it", "Preventing all locking"], answer: 1, exp: "The aborted transaction is rolled back and usually retried." },
  { id: "dl-29", topic: "os-deadlock", q: "wait-die and wound-wait are deadlock-PREVENTION schemes based on:", options: ["Resource ordering", "Transaction timestamps (age): decide whether an older or younger transaction waits or is aborted", "Priority", "Random choice"], answer: 1, exp: "Both prevent circular wait by only allowing waits in one age direction." },
  { id: "dl-30", topic: "os-deadlock", q: "In wait-die: when an OLDER transaction requests a lock held by a YOUNGER one:", options: ["The older is aborted", "The older waits", "The younger is aborted", "Both abort"], answer: 1, exp: "Older waits, younger 'dies' (aborts) if it requests an older's lock. Non-preemptive." },
  { id: "dl-31", topic: "os-deadlock", q: "In wound-wait: when an OLDER transaction requests a lock held by a YOUNGER one:", options: ["The older waits", "The older 'wounds' (preempts/aborts) the younger", "The older aborts", "Nothing happens"], answer: 1, exp: "Preemptive: older wounds younger; younger waits for older. Fewer aborts than wait-die typically." },
  { id: "dl-32", topic: "os-deadlock", q: "Both wait-die and wound-wait avoid starvation because:", options: ["They never abort", "An aborted transaction is restarted with its ORIGINAL (older) timestamp, so eventually it becomes the oldest and cannot be aborted", "They use random priorities", "The OS intervenes"], answer: 1, exp: "Keeping the timestamp guarantees forward progress." },
  { id: "dl-33", topic: "os-deadlock", q: "Timeout-based deadlock handling:", options: ["Is always accurate", "Aborts any transaction/process that waits longer than a threshold — simple but may abort non-deadlocked ones (false positives)", "Requires a wait-for graph", "Prevents deadlock"], answer: 1, exp: "Choosing the timeout is a tuning problem." },
  { id: "dl-34", topic: "os-deadlock", q: "Which is TRUE about deadlock in a system with a single resource type and single instance?", options: ["Deadlock is impossible", "Deadlock needs at least two resources (a process cannot deadlock waiting on one resource it does not hold)", "A cycle of length 1 causes it", "It always deadlocks"], answer: 1, exp: "You need at least two processes each holding one and wanting the other." },
  { id: "dl-35", topic: "os-deadlock", q: "Resource-allocation graph with a claim edge (dashed) is used for:", options: ["Detection", "Avoidance — a claim edge Pi --> Rj means Pi MAY request Rj; granting must not create a cycle", "Recovery", "Prevention"], answer: 1, exp: "This is the single-instance version of the Banker's algorithm." },
  { id: "dl-36", topic: "os-deadlock", q: "The main disadvantage of deadlock prevention:", options: ["It is unsafe", "Low device utilization and reduced system throughput (resources requested early / held long / denied unnecessarily)", "It requires max claims", "It causes livelock"], answer: 1, exp: "You pay a permanent efficiency cost to avoid an occasional deadlock." },
  { id: "dl-37", topic: "os-deadlock", q: "A process requests resources in the order R1, R2, R3 (by the global ordering) — this prevents:", options: ["Mutual exclusion", "Circular wait", "Starvation", "Page faults"], answer: 1, exp: "If every process requests in increasing order, no cycle can form." },
  { id: "dl-38", topic: "os-deadlock", q: "In the Banker's algorithm, if a request leaves the system in an UNSAFE state:", options: ["It is granted anyway", "The process is made to wait (the request is denied for now)", "The process is aborted", "The system deadlocks"], answer: 1, exp: "The resources stay available; the process retries later." },
  { id: "dl-39", topic: "os-deadlock", q: "Which is NOT one of the four Coffman conditions?", options: ["Mutual exclusion", "Hold and wait", "Bounded waiting", "Circular wait"], answer: 2, exp: "Bounded waiting is a critical-section requirement, not a deadlock condition. The fourth is 'no preemption'." },
  { id: "dl-40", topic: "os-deadlock", q: "Deadlock avoidance vs prevention:", options: ["They are the same", "Prevention constrains request patterns structurally; avoidance dynamically decides each request using future-need info", "Avoidance needs no information", "Prevention is dynamic"], answer: 1, exp: "Avoidance is less restrictive but needs advance knowledge and per-request computation." },
  { id: "dl-41", topic: "os-deadlock", q: "The Banker's algorithm is rarely used in practice because:", options: ["It is incorrect", "Processes seldom know their maximum resource needs in advance, and the number of resources/processes varies", "It is too fast", "It only works for one process"], answer: 1, exp: "Its assumptions do not fit general-purpose systems." },
  { id: "dl-42", topic: "os-deadlock", q: "A single global lock (giant lock) for the whole kernel:", options: ["Causes frequent deadlock", "Prevents deadlock among kernel data structures but destroys multiprocessor scalability", "Is lock-free", "Is the modern approach"], answer: 1, exp: "Modern kernels use fine-grained locking (and must then manage lock ordering)." },
  { id: "dl-43", topic: "os-deadlock", q: "If a thread tries to lock a non-recursive mutex it already holds:", options: ["It succeeds", "It self-deadlocks (blocks forever waiting for itself)", "The mutex is freed", "An error is always returned"], answer: 1, exp: "Use a recursive mutex, or restructure so the lock is taken once." },
  { id: "dl-44", topic: "os-deadlock", q: "The 'try-lock and backoff' technique for two locks:", options: ["Guarantees no starvation", "Acquires lock1, then trylock(lock2); on failure, release lock1, wait a random interval, retry — avoids deadlock but can livelock without randomization", "Is the same as ordered locking", "Requires the Banker's algorithm"], answer: 1, exp: "Randomized backoff makes repeated collisions unlikely." },
  { id: "dl-45", topic: "os-deadlock", q: "Which condition does 'allow a process to request a resource only if it holds none' break?", options: ["Circular wait", "Hold and wait", "No preemption", "Mutual exclusion"], answer: 1, exp: "It must release everything before requesting more." },
  { id: "dl-46", topic: "os-deadlock", q: "A deadlock involving I/O devices (e.g. two tape drives) is best handled by:", options: ["Ignoring it", "Requiring processes to declare and acquire all needed devices before starting (prevention), or using spooling", "Preempting the tape mid-write", "Adding more processes"], answer: 1, exp: "Spooling (e.g. print spoolers) virtualizes the device so it is effectively sharable." },
  { id: "dl-47", topic: "os-deadlock", q: "The number of edges in a resource-allocation graph deadlock cycle equals:", options: ["Always 2", "Twice the number of processes in the cycle (each process has a request edge in and an assignment edge out, alternating P and R nodes)", "The number of resources", "1"], answer: 1, exp: "The cycle alternates process and resource nodes." },
  { id: "dl-48", topic: "os-deadlock", q: "Which is TRUE: a system in an unsafe state:", options: ["Is always deadlocked", "Is not necessarily deadlocked, but the OS can no longer guarantee that deadlock will be avoided", "Is safe", "Has no free resources"], answer: 1, exp: "Unsafe = 'we lost the guarantee', not 'deadlock now'." },
  { id: "dl-49", topic: "os-deadlock", q: "Combining approaches (as real systems do) means:", options: ["Using all three for every resource", "Partitioning resources into classes and applying the most appropriate technique to each class", "Only using detection", "Only using the ostrich algorithm"], answer: 1, exp: "e.g. ordered locking for internal locks, prevention for swap space, ostrich for user memory." },
  { id: "dl-50", topic: "os-deadlock", q: "The simplest and most common developer-level rule to avoid lock-based deadlock is:", options: ["Never use locks", "Always acquire multiple locks in a consistent, documented global order (and release in reverse)", "Use only spinlocks", "Acquire locks randomly"], answer: 1, exp: "A lock hierarchy makes circular wait impossible." },

  // ================= CPU Scheduling (50) =================
  { id: "cs-01", topic: "os-scheduling", q: "The goal of CPU scheduling is to:", options: ["Run one process at a time", "Decide which ready process gets the CPU next, to optimize metrics like throughput, turnaround, waiting and response time", "Free memory", "Handle interrupts"], answer: 1, exp: "Different algorithms favor different metrics; there is no universally best one." },
  { id: "cs-02", topic: "os-scheduling", q: "FCFS (First-Come First-Served) scheduling is:", options: ["Preemptive and fair", "Non-preemptive; simple; suffers the convoy effect (short jobs stuck behind a long one)", "Optimal for turnaround", "Priority-based"], answer: 1, exp: "A long CPU-bound job at the front delays everyone." },
  { id: "cs-03", topic: "os-scheduling", q: "SJF (Shortest Job First) is optimal for:", options: ["Response time", "Minimizing average waiting time (and average turnaround) — provably optimal", "Fairness", "Throughput of long jobs"], answer: 1, exp: "But it needs to know/predict burst lengths and can starve long jobs." },
  { id: "cs-04", topic: "os-scheduling", q: "The preemptive version of SJF is:", options: ["Round Robin", "Shortest Remaining Time First (SRTF)", "FCFS", "Priority (non-preemptive)"], answer: 1, exp: "A newly arrived job with a shorter remaining time preempts the running one." },
  { id: "cs-05", topic: "os-scheduling", q: "Round Robin (RR) scheduling:", options: ["Runs jobs to completion", "Gives each ready process a fixed time quantum in turn (preemptive, FIFO ready queue)", "Is the same as SJF", "Has no context switches"], answer: 1, exp: "Good response time; performance depends heavily on the quantum size." },
  { id: "cs-06", topic: "os-scheduling", q: "If the RR time quantum is too small:", options: ["Response time worsens", "Context-switch overhead dominates (too much time spent switching, not computing)", "It behaves like SJF", "Starvation occurs"], answer: 1, exp: "Too large a quantum makes RR degenerate into FCFS." },
  { id: "cs-07", topic: "os-scheduling", q: "The convoy effect occurs in:", options: ["Round Robin", "FCFS — many short I/O-bound processes wait behind one long CPU-bound process", "SJF", "Multilevel feedback"], answer: 1, exp: "It reduces both CPU and device utilization." },
  { id: "cs-08", topic: "os-scheduling", q: "Priority scheduling's main problem is:", options: ["It is too fair", "Starvation (indefinite blocking) of low-priority processes", "It cannot be preemptive", "It needs burst times"], answer: 1, exp: "Aging — gradually increasing a waiting process's priority — is the standard cure." },
  { id: "cs-09", topic: "os-scheduling", q: "Aging in scheduling means:", options: ["Killing old processes", "Increasing the priority of processes that have waited a long time, to prevent starvation", "Lowering priority over time", "Deleting the ready queue"], answer: 1, exp: "It bounds the waiting time of any process." },
  { id: "cs-10", topic: "os-scheduling", q: "Multilevel queue scheduling:", options: ["Uses one queue", "Partitions the ready queue into several queues (e.g. system, interactive, batch), each with its own policy; processes do not move between queues", "Is the same as RR", "Moves processes freely"], answer: 1, exp: "Scheduling between queues is often fixed-priority or time-sliced." },
  { id: "cs-11", topic: "os-scheduling", q: "Multilevel FEEDBACK queue scheduling:", options: ["Never moves processes", "Lets processes move between queues based on behavior — CPU-heavy processes drop to lower-priority (longer-quantum) queues; I/O-heavy processes stay high", "Uses only FCFS", "Requires known burst times"], answer: 1, exp: "It approximates SJF without knowing burst lengths in advance." },
  { id: "cs-12", topic: "os-scheduling", q: "Given processes with burst times 6, 8, 7, 3 (FCFS in that order), the average waiting time is:", options: ["0", "(0 + 6 + 14 + 21) / 4 = 10.25", "6", "24"], answer: 1, exp: "Waiting = start time - arrival (all arrive at 0): 0, 6, 14, 21 => avg 10.25." },
  { id: "cs-13", topic: "os-scheduling", q: "For the same jobs (6, 8, 7, 3) under SJF, the order is 3, 6, 7, 8 and average waiting time is:", options: ["10.25", "(0 + 3 + 9 + 16) / 4 = 7", "3", "24"], answer: 1, exp: "SJF gives a lower average waiting time than FCFS — 7 vs 10.25." },
  { id: "cs-14", topic: "os-scheduling", q: "Response time is:", options: ["Total time in the system", "Time from submission until the process FIRST starts responding (first gets the CPU)", "CPU burst length", "I/O wait time"], answer: 1, exp: "RR optimizes response time; interactive systems care about it most." },
  { id: "cs-15", topic: "os-scheduling", q: "Throughput is:", options: ["The time to finish one job", "The number of processes completed per unit time", "The waiting time", "CPU idle time"], answer: 1, exp: "Batch systems maximize throughput; long jobs help throughput but hurt response time." },
  { id: "cs-16", topic: "os-scheduling", q: "CPU utilization is:", options: ["The percentage of time the CPU is busy (doing useful or OS work)", "The number of cores", "The clock speed", "The number of processes"], answer: 0, exp: "Goal: keep it high (40-90% in real systems)." },
  { id: "cs-17", topic: "os-scheduling", q: "SJF burst-length prediction commonly uses:", options: ["The exact next burst (known)", "Exponential averaging: tau(n+1) = alpha * t(n) + (1 - alpha) * tau(n)", "A random guess", "The process priority"], answer: 1, exp: "It weights recent history; alpha controls how fast it adapts." },
  { id: "cs-18", topic: "os-scheduling", q: "A non-preemptive scheduler makes a decision only when a process:", options: ["Arrives", "Terminates or blocks (moves from running to waiting)", "Is preempted by the timer", "Requests more memory"], answer: 1, exp: "Preemptive schedulers also decide on timer interrupts and new arrivals." },
  { id: "cs-19", topic: "os-scheduling", q: "The dispatch latency is:", options: ["Time a process waits in the ready queue", "The time the dispatcher takes to stop one process and start another (context switch + mode switch + jump)", "The quantum length", "I/O time"], answer: 1, exp: "Real-time systems need low, bounded dispatch latency." },
  { id: "cs-20", topic: "os-scheduling", q: "In RR, a process that uses only part of its quantum (blocks on I/O):", options: ["Loses its turn permanently", "Goes to the waiting queue; when ready again it rejoins the tail of the ready queue", "Gets a longer quantum next time", "Keeps the CPU"], answer: 1, exp: "It forfeits the rest of the quantum." },
  { id: "cs-21", topic: "os-scheduling", q: "Which scheduler is best for a purely interactive system?", options: ["FCFS", "Round Robin or a multilevel feedback queue (good response time)", "Non-preemptive SJF", "Longest Job First"], answer: 1, exp: "Users want quick reaction to input." },
  { id: "cs-22", topic: "os-scheduling", q: "Real-time scheduling: a HARD real-time task:", options: ["Should usually meet its deadline", "MUST meet its deadline or the result is a system failure", "Has no deadline", "Runs at low priority"], answer: 1, exp: "Soft real-time: missing a deadline degrades quality but is tolerable (e.g. video)." },
  { id: "cs-23", topic: "os-scheduling", q: "Rate-Monotonic Scheduling (RMS) assigns priority:", options: ["By deadline", "By period — shorter period gets higher priority (static priorities)", "By burst length", "Round robin"], answer: 1, exp: "Optimal among fixed-priority schemes; schedulable if total utilization <= n(2^(1/n) - 1) (~0.69 as n grows)." },
  { id: "cs-24", topic: "os-scheduling", q: "Earliest Deadline First (EDF) scheduling:", options: ["Uses static priorities", "Dynamically gives the CPU to the ready task with the nearest deadline; optimal for uniprocessors (100% utilization possible)", "Is the same as RMS", "Cannot preempt"], answer: 1, exp: "More flexible than RMS but harder to analyze and behaves worse under overload." },
  { id: "cs-25", topic: "os-scheduling", q: "Linux's default scheduler (CFS - Completely Fair Scheduler) tries to:", options: ["Run the shortest job", "Give each runnable task a fair share of CPU proportional to its weight, tracking 'virtual runtime'", "Use strict priorities", "Never preempt"], answer: 1, exp: "The task with the smallest vruntime runs next; implemented with a red-black tree." },
  { id: "cs-26", topic: "os-scheduling", q: "Gang scheduling is used for:", options: ["I/O devices", "Scheduling all threads of a parallel job simultaneously across CPUs so they can communicate without waiting", "Batch jobs", "Real-time tasks"], answer: 1, exp: "Avoids the situation where a thread spins waiting for a descheduled peer." },
  { id: "cs-27", topic: "os-scheduling", q: "Processor affinity is beneficial because:", options: ["It balances load", "Keeping a process on the same CPU preserves its warm cache (soft affinity) or is required (hard affinity)", "It uses less memory", "It prevents deadlock"], answer: 1, exp: "Migration causes cache misses on the new core." },
  { id: "cs-28", topic: "os-scheduling", q: "Load balancing in a multiprocessor moves processes:", options: ["To CPU 0 always", "From busy CPUs to idle ones — via push migration (a task checks and pushes) or pull migration (an idle CPU pulls)", "To disk", "Randomly every quantum"], answer: 1, exp: "It trades cache affinity for utilization." },
  { id: "cs-29", topic: "os-scheduling", q: "In SRTF (preemptive SJF), when a new short job arrives:", options: ["It waits", "It preempts the running job if its (total) burst is shorter than the running job's REMAINING time", "It is rejected", "It runs after the current quantum"], answer: 1, exp: "This is what makes it 'shortest remaining time'." },
  { id: "cs-30", topic: "os-scheduling", q: "A drawback of SRTF/SJF is:", options: ["Poor average waiting time", "Starvation of long jobs and the impracticality of knowing burst times", "Too many context switches only", "It is non-preemptive"], answer: 1, exp: "Long jobs may never run if short jobs keep arriving." },
  { id: "cs-31", topic: "os-scheduling", q: "The lottery scheduling approach:", options: ["Runs the highest bidder", "Gives each process 'tickets'; a random draw each quantum picks the winner, giving proportional-share fairness probabilistically", "Is strictly priority-based", "Never randomizes"], answer: 1, exp: "Simple, starvation-resistant, and priorities map to ticket counts." },
  { id: "cs-32", topic: "os-scheduling", q: "The 'quantum expired' event in RR triggers:", options: ["Process termination", "A timer interrupt -> the scheduler moves the running process to the ready queue tail and dispatches the next", "A page fault", "An I/O request"], answer: 1, exp: "The periodic timer interrupt is what makes preemption possible." },
  { id: "cs-33", topic: "os-scheduling", q: "For a mix of I/O-bound and CPU-bound processes, a good policy:", options: ["Favors CPU-bound processes", "Favors I/O-bound processes (short bursts) so they issue I/O quickly, keeping devices busy while CPU-bound ones use the CPU", "Runs them FCFS", "Runs only CPU-bound ones"], answer: 1, exp: "Multilevel feedback queues naturally keep interactive/I/O jobs at high priority." },
  { id: "cs-34", topic: "os-scheduling", q: "Which metric does FCFS handle worst?", options: ["Throughput", "Average waiting time / response time when a long job arrives first (convoy effect)", "CPU utilization", "Fairness of arrival order"], answer: 1, exp: "It is fair by arrival but terrible for average wait with mixed burst lengths." },
  { id: "cs-35", topic: "os-scheduling", q: "Given 3 processes, all arriving at t=0, bursts 10, 1, 2, under SRTF the completion order is:", options: ["10, 1, 2", "1, 2, 10", "2, 1, 10", "1, 10, 2"], answer: 1, exp: "Run the shortest remaining: P2 (1), then P3 (2), then P1 (10)." },
  { id: "cs-36", topic: "os-scheduling", q: "The scheduler is invoked (in a preemptive OS) on:", options: ["Only process termination", "Timer interrupts, I/O completion interrupts, process creation/termination, and blocking system calls", "Only page faults", "Every instruction"], answer: 1, exp: "Any event that changes the set of runnable processes or the running one's eligibility." },
  { id: "cs-37", topic: "os-scheduling", q: "Two-level scheduling separates:", options: ["User and kernel threads", "An in-memory scheduler (which of the resident processes runs) from a swapper (which processes are kept in memory)", "FCFS and SJF", "Real-time and batch"], answer: 1, exp: "Useful when not all processes fit in memory." },
  { id: "cs-38", topic: "os-scheduling", q: "Priority inversion in a scheduling context is mitigated by:", options: ["Round robin", "Priority inheritance or priority ceiling protocols", "Aging only", "Disabling priorities"], answer: 1, exp: "The lock holder temporarily runs at the waiter's priority." },
  { id: "cs-39", topic: "os-scheduling", q: "In RR with quantum q and n processes, the worst-case time a process waits for the CPU is about:", options: ["q", "(n - 1) * q", "n * q * q", "0"], answer: 1, exp: "It must wait for each of the other n-1 processes to use up to a full quantum." },
  { id: "cs-40", topic: "os-scheduling", q: "Which is TRUE about SJF vs FCFS average waiting time?", options: ["FCFS is always lower", "SJF gives the minimum possible average waiting time for a given set of jobs", "They are always equal", "SJF is higher"], answer: 1, exp: "Provable by an exchange argument (shortest-processing-time-first)." },
  { id: "cs-41", topic: "os-scheduling", q: "A tickless (dynamic tick) kernel:", options: ["Never schedules", "Avoids a fixed periodic timer interrupt when a CPU is idle or running a single task, saving power", "Uses RR only", "Cannot preempt"], answer: 1, exp: "It programs a one-shot timer for the next actual deadline." },
  { id: "cs-42", topic: "os-scheduling", q: "The 'nice' value on Linux maps to:", options: ["A hard priority", "A weight in CFS that scales the task's CPU share (each nice level ~ 1.25x)", "The time quantum directly", "The PID"], answer: 1, exp: "Lower nice (higher priority) => larger weight => more CPU." },
  { id: "cs-43", topic: "os-scheduling", q: "Batch scheduling (e.g. HPC job schedulers like Slurm) primarily optimizes:", options: ["Interactive response time", "Throughput and resource utilization; jobs queue and run to completion", "Fairness per keystroke", "Real-time deadlines"], answer: 1, exp: "Users submit jobs and wait; the scheduler packs the cluster." },
  { id: "cs-44", topic: "os-scheduling", q: "For a real-time periodic task set, EDF can achieve schedulable utilization up to:", options: ["69%", "100% (on a uniprocessor)", "50%", "It depends on the number of tasks"], answer: 1, exp: "RMS is limited to ~69% (Liu & Layland bound); EDF hits 100%." },
  { id: "cs-45", topic: "os-scheduling", q: "The main cost that all preemptive schedulers pay is:", options: ["Memory", "Context-switch overhead (pure overhead, no useful work)", "Disk I/O", "Network latency"], answer: 1, exp: "Minimized by choosing quanta large enough that switching is a small fraction of runtime." },
  { id: "cs-46", topic: "os-scheduling", q: "Which scheduling metric matters most for a video-streaming decoder thread?", options: ["Throughput", "Meeting soft real-time deadlines (frame every ~16-33 ms)", "Turnaround time", "Ticket count"], answer: 1, exp: "Consistent, timely CPU access matters more than raw throughput." },
  { id: "cs-47", topic: "os-scheduling", q: "A process that alternates short CPU bursts with I/O is classified as:", options: ["CPU-bound", "I/O-bound", "Real-time", "Batch"], answer: 1, exp: "Schedulers favor these to keep devices utilized." },
  { id: "cs-48", topic: "os-scheduling", q: "The ready queue in a priority scheduler is often implemented as:", options: ["A stack", "A priority queue (heap) or an array of FIFO queues indexed by priority level", "A hash table", "A binary search tree of PIDs"], answer: 1, exp: "O(1) or O(log n) to find the highest-priority ready task." },
  { id: "cs-49", topic: "os-scheduling", q: "Given bursts and RR quantum 4, jobs A(8) B(4) C(9): after the first round the ready queue (tail-first order of what remains) is:", options: ["A(4), C(5) [B finished]", "A(8), B(4), C(9)", "B(4), C(9)", "empty"], answer: 0, exp: "Round 1: A runs 4 (rem 4), B runs 4 (done), C runs 4 (rem 5). Queue: A(4), C(5)." },
  { id: "cs-50", topic: "os-scheduling", q: "There is no single best scheduling algorithm because:", options: ["Hardware is too slow", "Different workloads and goals (throughput vs response vs fairness vs deadlines) call for different tradeoffs", "Scheduling is unsolved", "Algorithms are secret"], answer: 1, exp: "Real OSes use tunable hybrids (multilevel feedback, CFS) to balance competing objectives." },

  // ================= Memory & Virtual Memory (50) =================
  { id: "mm-01", topic: "os-memory", q: "The purpose of virtual memory is to:", options: ["Make RAM faster", "Give each process a large, private, contiguous-looking address space, using disk to extend physical memory and enabling isolation", "Remove the need for RAM", "Speed up the CPU"], answer: 1, exp: "It also enables demand paging, sharing, and protection." },
  { id: "mm-02", topic: "os-memory", q: "Paging divides:", options: ["Only physical memory", "Virtual memory into fixed-size pages and physical memory into equal-size frames; a page maps to any frame", "Memory into variable-size segments", "The disk only"], answer: 1, exp: "Fixed size eliminates external fragmentation." },
  { id: "mm-03", topic: "os-memory", q: "A page table maps:", options: ["Frames to pages", "Virtual page numbers to physical frame numbers (per process)", "Files to blocks", "Processes to CPUs"], answer: 1, exp: "The MMU consults it (via the TLB) on every memory access." },
  { id: "mm-04", topic: "os-memory", q: "Internal fragmentation in paging comes from:", options: ["Gaps between allocations", "The last page of an allocation being only partially used (wasted space within a page)", "The page table", "Swapping"], answer: 1, exp: "Average waste ~ half a page per region; smaller pages reduce it but enlarge the page table." },
  { id: "mm-05", topic: "os-memory", q: "External fragmentation occurs with:", options: ["Paging", "Variable-size partition allocation / segmentation — free memory is split into small non-contiguous holes", "Fixed frames", "The TLB"], answer: 1, exp: "Compaction can fix it but is expensive; paging avoids it entirely." },
  { id: "mm-06", topic: "os-memory", q: "The TLB (Translation Lookaside Buffer) is:", options: ["A page table on disk", "A small associative cache of recent page-table entries in the MMU", "The swap area", "A CPU register"], answer: 1, exp: "A TLB miss triggers a page-table walk (hardware or software)." },
  { id: "mm-07", topic: "os-memory", q: "Effective access time with a TLB hit ratio of 98%, TLB access 1 ns, memory access 100 ns (one-level table):", options: ["100 ns", "0.98(101) + 0.02(201) = 103 ns", "200 ns", "1 ns"], answer: 1, exp: "Hit: TLB + memory. Miss: TLB + page-table memory access + data memory access." },
  { id: "mm-08", topic: "os-memory", q: "A page fault occurs when:", options: ["The page table is full", "A referenced page is not currently in physical memory (valid bit clear)", "The TLB is full", "Two processes share a page"], answer: 1, exp: "The OS loads the page from disk (or the file), updates the table, and restarts the instruction." },
  { id: "mm-09", topic: "os-memory", q: "Demand paging means:", options: ["All pages are loaded at process start", "Pages are loaded into memory only when first referenced (lazy loading)", "The whole program is on disk", "Pages are never evicted"], answer: 1, exp: "It reduces startup time and memory use; the first touch of each page costs a fault." },
  { id: "mm-10", topic: "os-memory", q: "The optimal (OPT / Belady's) page-replacement algorithm evicts:", options: ["The oldest page", "The page that will not be used for the longest time in the future", "The least recently used page", "A random page"], answer: 1, exp: "It is unrealizable (needs the future) but is the benchmark for others." },
  { id: "mm-11", topic: "os-memory", q: "FIFO page replacement can suffer from:", options: ["Optimal behavior", "Belady's anomaly — more frames can cause MORE page faults", "No faults ever", "TLB thrashing only"], answer: 1, exp: "LRU and OPT are 'stack algorithms' and never show this anomaly." },
  { id: "mm-12", topic: "os-memory", q: "LRU (Least Recently Used) replacement evicts:", options: ["The page loaded first", "The page that has not been accessed for the longest time", "The largest page", "A random page"], answer: 1, exp: "Exact LRU needs a timestamp or a stack per access (expensive); approximations are used." },
  { id: "mm-13", topic: "os-memory", q: "The 'clock' (second-chance) algorithm approximates LRU using:", options: ["Full timestamps", "A reference bit per page; on a sweep, a page with ref=1 gets its bit cleared and a second chance; ref=0 is evicted", "The page table size", "Random selection"], answer: 1, exp: "Cheap hardware support (one bit) and good approximation of LRU." },
  { id: "mm-14", topic: "os-memory", q: "Thrashing is:", options: ["Fast paging", "A state where processes spend more time paging than executing, because the sum of working sets exceeds physical memory", "A disk failure", "TLB misses"], answer: 1, exp: "CPU utilization collapses; the fix is to reduce the degree of multiprogramming (swap out a process)." },
  { id: "mm-15", topic: "os-memory", q: "The working set of a process is:", options: ["Its total address space", "The set of pages it has referenced in the last Delta (working-set window) time units", "Its page table", "The frames it will never use"], answer: 1, exp: "The working-set model keeps a process's working set in memory to avoid thrashing." },
  { id: "mm-16", topic: "os-memory", q: "Segmentation divides memory into:", options: ["Fixed-size pages", "Variable-size, logically meaningful units (code, stack, heap, a table) — matching the programmer's view", "Frames", "Blocks"], answer: 1, exp: "It suffers external fragmentation; modern systems combine segmentation with paging." },
  { id: "mm-17", topic: "os-memory", q: "A multi-level (hierarchical) page table is used because:", options: ["It is faster", "A single flat page table for a 64-bit address space would be enormous; multi-level tables only allocate entries for used regions", "It uses no memory", "It avoids the TLB"], answer: 1, exp: "e.g. x86-64 uses a 4- or 5-level table; each level indexes a slice of the virtual address." },
  { id: "mm-18", topic: "os-memory", q: "An inverted page table has one entry per:", options: ["Virtual page", "Physical frame (mapping frame -> <pid, virtual page>), so its size is proportional to physical, not virtual, memory", "Process", "Segment"], answer: 1, exp: "It saves space but makes address translation a search (mitigated by hashing)." },
  { id: "mm-19", topic: "os-memory", q: "The valid/invalid (present) bit in a page-table entry indicates:", options: ["Whether the page is dirty", "Whether the page is currently in physical memory (valid) or must be faulted in (invalid)", "The access permissions", "The page size"], answer: 1, exp: "Other PTE bits: dirty, referenced/accessed, read/write, user/supervisor, no-execute." },
  { id: "mm-20", topic: "os-memory", q: "The dirty (modified) bit is used to:", options: ["Mark corrupt pages", "Avoid writing an unmodified page back to disk on eviction (clean pages can just be discarded)", "Track access time", "Set permissions"], answer: 1, exp: "It halves eviction cost for read-only / unmodified pages." },
  { id: "mm-21", topic: "os-memory", q: "Copy-on-write (COW) pages allow fork() to:", options: ["Copy all memory immediately", "Share the parent's pages read-only; a private copy is made only when the child or parent writes", "Prevent the child from writing", "Double memory instantly"], answer: 1, exp: "Efficient when fork() is followed by exec()." },
  { id: "mm-22", topic: "os-memory", q: "Memory-mapped files (mmap):", options: ["Load the whole file into RAM", "Map a file's contents into the address space so it can be accessed with ordinary loads/stores; the OS pages it in on demand", "Are slower than read()", "Cannot be shared"], answer: 1, exp: "Also used for shared memory and for loading executables/libraries." },
  { id: "mm-23", topic: "os-memory", q: "Belady's anomaly is impossible for:", options: ["FIFO", "Stack algorithms like LRU and OPT (the set of pages in memory with n frames is a subset of that with n+1)", "Any algorithm", "Random replacement"], answer: 1, exp: "The stack property guarantees monotone improvement with more frames." },
  { id: "mm-24", topic: "os-memory", q: "The page size is a tradeoff:", options: ["Bigger is always better", "Larger pages reduce page-table size and TLB pressure but increase internal fragmentation and I/O waste; smaller pages do the opposite", "Smaller is always better", "It does not matter"], answer: 1, exp: "Many systems support 'huge pages' (2 MB, 1 GB) for large workloads." },
  { id: "mm-25", topic: "os-memory", q: "Swap space is:", options: ["Fast cache", "Disk area used to hold pages evicted from physical memory (and, historically, whole swapped-out processes)", "Part of the CPU", "The page table"], answer: 1, exp: "Running out of both RAM and swap triggers the OOM killer on Linux." },
  { id: "mm-26", topic: "os-memory", q: "The three-level 'address translation' path (worst case, no caching) for a 3-level page table costs:", options: ["1 memory access", "4 memory accesses (3 page-table levels + 1 data)", "2 accesses", "0 accesses"], answer: 1, exp: "The TLB avoids this on a hit; hence its importance." },
  { id: "mm-27", topic: "os-memory", q: "A TLB flush is required on:", options: ["Every memory access", "A context switch (to a process with a different address space), unless the TLB is tagged with an address-space ID (ASID/PCID)", "A page hit", "Reading a register"], answer: 1, exp: "ASIDs let entries from multiple processes coexist, avoiding flushes." },
  { id: "mm-28", topic: "os-memory", q: "The 'reference string' in page-replacement analysis is:", options: ["The list of frames", "The sequence of page numbers a process accesses", "The page table", "The swap file"], answer: 1, exp: "Algorithms are compared by counting faults over a given reference string and frame count." },
  { id: "mm-29", topic: "os-memory", q: "Global vs local page replacement: local replacement:", options: ["Lets a process take frames from any process", "Restricts a faulting process to replacing among its OWN frames — its fault rate is stable but frame allocation may be suboptimal", "Is the same as global", "Prevents faults"], answer: 1, exp: "Global replacement adapts better but one process's behavior affects others' fault rates." },
  { id: "mm-30", topic: "os-memory", q: "The page-fault frequency (PFF) scheme controls thrashing by:", options: ["Fixing the frame count", "Raising a process's frame allocation if its fault rate is too high, lowering it if too low", "Swapping everything out", "Using bigger pages"], answer: 1, exp: "It directly targets the symptom (fault rate)." },
  { id: "mm-31", topic: "os-memory", q: "Prepaging (anticipatory paging) is:", options: ["Loading pages after they fault", "Loading pages into memory BEFORE they are referenced, guessing future needs (e.g. a process's working set at swap-in)", "The same as demand paging", "Never useful"], answer: 1, exp: "It reduces fault count if the guess is good; wastes I/O if not." },
  { id: "mm-32", topic: "os-memory", q: "Which is TRUE about pure segmentation vs pure paging?", options: ["Segmentation has internal fragmentation, paging has external", "Paging has internal fragmentation and a transparent fixed-size layout; segmentation has external fragmentation and matches the logical program structure", "Both have neither", "They are identical"], answer: 1, exp: "Combined schemes (paged segmentation) aim to get the best of both." },
  { id: "mm-33", topic: "os-memory", q: "The 'accessed' (reference) bit is set by:", options: ["The programmer", "The hardware (MMU) whenever the page is read or written", "The compiler", "The disk"], answer: 1, exp: "The OS periodically clears it to track recent usage for replacement decisions." },
  { id: "mm-34", topic: "os-memory", q: "A process's resident set size (RSS) is:", options: ["Its virtual address space size", "The portion of its pages currently in physical RAM", "Its swap usage", "Its page-table size"], answer: 1, exp: "Virtual size (VSZ) can be much larger than RSS (unused / not-yet-faulted / shared pages)." },
  { id: "mm-35", topic: "os-memory", q: "Contiguous memory allocation with first-fit / best-fit / worst-fit refers to choosing:", options: ["A page frame", "Which free hole to place a variable-size allocation in", "A replacement victim", "A TLB entry"], answer: 1, exp: "First-fit is fast; best-fit leaves tiny holes; worst-fit leaves large ones. All suffer external fragmentation." },
  { id: "mm-36", topic: "os-memory", q: "The buddy system allocator:", options: ["Splits memory into power-of-two blocks, splitting/coalescing 'buddies' on allocation/free — fast coalescing, some internal fragmentation", "Uses linked lists of exact-size blocks only", "Never coalesces", "Is used for page tables"], answer: 0, exp: "Linux uses it for physical page allocation; the slab allocator sits on top for small objects." },
  { id: "mm-37", topic: "os-memory", q: "When a page-fault handler finds no free frame, it must:", options: ["Crash", "Run the page-replacement algorithm to evict a victim (writing it back if dirty), then load the needed page", "Return an error to the process", "Grow physical memory"], answer: 1, exp: "This is the core of demand paging under memory pressure." },
  { id: "mm-38", topic: "os-memory", q: "Which reference string + 3 frames shows Belady's anomaly is AVOIDED by LRU but not FIFO? (concept)", options: ["LRU never has the anomaly; FIFO can (e.g. 1,2,3,4,1,2,5,1,2,3,4,5)", "Both have it", "Neither has it", "Only LRU has it"], answer: 0, exp: "The famous string 1 2 3 4 1 2 5 1 2 3 4 5 gives more faults with 4 FIFO frames than with 3." },
  { id: "mm-39", topic: "os-memory", q: "The OS keeps a pool of free frames ('zeroed page' pool) so that:", options: ["Memory is wasted", "A page fault can be satisfied immediately without waiting for a write-back, improving fault latency", "Processes cannot allocate", "The TLB stays warm"], answer: 1, exp: "A background thread reclaims and zeroes frames ahead of demand (e.g. Linux's kswapd)." },
  { id: "mm-40", topic: "os-memory", q: "Address space layout randomization (ASLR):", options: ["Speeds up translation", "Randomizes the base addresses of the stack, heap and libraries to make memory-corruption exploits harder", "Compresses memory", "Is a replacement algorithm"], answer: 1, exp: "A security mitigation implemented in the loader / kernel." },
  { id: "mm-41", topic: "os-memory", q: "The relationship between logical and physical address in simple paging: given page size 2^k, the low k bits are:", options: ["The page number", "The offset within the page, copied unchanged into the physical address", "Always zero", "The frame number"], answer: 1, exp: "The high bits (page number) are translated; the offset passes through." },
  { id: "mm-42", topic: "os-memory", q: "A 32-bit virtual address with 4 KB pages has:", options: ["12-bit page number, 20-bit offset", "20-bit page number, 12-bit offset (2^20 pages, 2^12 offset)", "16-bit each", "32-bit offset"], answer: 1, exp: "4 KB = 2^12, so 12 offset bits; the remaining 20 bits index 2^20 pages." },
  { id: "mm-43", topic: "os-memory", q: "Shared libraries (DLLs / .so) save memory because:", options: ["They are compressed", "One physical copy of the read-only code pages is mapped into every process that uses the library", "They run in the kernel", "They are never loaded"], answer: 1, exp: "Only the writable data segment is per-process (often COW)." },
  { id: "mm-44", topic: "os-memory", q: "The OOM (out-of-memory) killer:", options: ["Adds RAM", "Selects and kills a process (by a heuristic 'badness' score) when the system cannot reclaim enough memory", "Compresses pages", "Swaps to the cloud"], answer: 1, exp: "A last resort to keep the system alive; tunable via oom_score_adj." },
  { id: "mm-45", topic: "os-memory", q: "zswap / zram compress:", options: ["The page table", "Pages that would be swapped, keeping them compressed in RAM instead of (or before) writing to disk", "The TLB", "Executables"], answer: 1, exp: "Trades CPU for reduced/avoided disk I/O on swap." },
  { id: "mm-46", topic: "os-memory", q: "Which page-replacement algorithm is guaranteed optimal but not implementable?", options: ["LRU", "FIFO", "OPT (Belady's) — it needs knowledge of future references", "Clock"], answer: 2, exp: "It serves only as a lower bound for comparison." },
  { id: "mm-47", topic: "os-memory", q: "The main reason NOT to make pages very large (e.g. 1 MB) by default:", options: ["Page tables get bigger", "Internal fragmentation and I/O amplification — small allocations and small file reads waste a whole large page", "Translation is slower", "The TLB cannot cache them"], answer: 1, exp: "Huge pages are opt-in for workloads with large contiguous footprints." },
  { id: "mm-48", topic: "os-memory", q: "In a system with paging, protection (read-only, no-execute) is enforced:", options: ["By the compiler", "By permission bits in each page-table entry, checked by the MMU on every access", "By the disk controller", "Only at load time"], answer: 1, exp: "A violation raises a fault (e.g. SIGSEGV)." },
  { id: "mm-49", topic: "os-memory", q: "The working-set window Delta being too large:", options: ["Prevents thrashing perfectly", "Includes pages no longer needed, over-estimating the working set and reducing the multiprogramming level", "Causes Belady's anomaly", "Has no effect"], answer: 1, exp: "Too small a Delta excludes needed pages, causing faults. Tuning Delta is key." },
  { id: "mm-50", topic: "os-memory", q: "Virtual memory's key enabler in hardware is:", options: ["A faster clock", "The MMU performing address translation and protection checks transparently on every memory reference", "More cache", "DMA"], answer: 1, exp: "Without hardware translation, every access would need OS intervention — far too slow." },

  // ================= File Systems (50) =================
  { id: "fs-01", topic: "os-filesystems", q: "A file is:", options: ["A block on disk", "A named collection of related information, an OS abstraction over storage", "A directory", "A process"], answer: 1, exp: "The file system maps this logical view onto physical blocks." },
  { id: "fs-02", topic: "os-filesystems", q: "An inode (index node) stores:", options: ["The file's name", "File metadata (size, permissions, timestamps, owner) and pointers to the file's data blocks — but NOT the name", "Only the data", "The directory tree"], answer: 1, exp: "The name lives in the directory entry, which maps name -> inode number." },
  { id: "fs-03", topic: "os-filesystems", q: "A hard link is:", options: ["A shortcut file", "An additional directory entry pointing to the same inode; the file's data persists until the link count reaches 0", "A pointer to another path (that can dangle)", "A copy of the file"], answer: 1, exp: "Hard links cannot cross file systems or (usually) link directories." },
  { id: "fs-04", topic: "os-filesystems", q: "A symbolic (soft) link is:", options: ["Another name for the same inode", "A special file containing a path to the target; it can dangle if the target is removed and can cross file systems", "A hard link to a directory", "A backup"], answer: 1, exp: "Resolving it is an extra lookup; removing the target leaves a broken link." },
  { id: "fs-05", topic: "os-filesystems", q: "Contiguous file allocation:", options: ["Has no fragmentation", "Stores a file in consecutive blocks — fast sequential/random access but suffers external fragmentation and hard to grow files", "Uses a linked list", "Uses an index block"], answer: 1, exp: "Used on CDs/DVDs and some real-time systems." },
  { id: "fs-06", topic: "os-filesystems", q: "Linked allocation:", options: ["Stores a pointer to the next block in each block — no external fragmentation, but poor random access and pointer overhead", "Is the fastest for random access", "Uses an index node", "Requires contiguous space"], answer: 0, exp: "The FAT file system uses a variant with the links in a separate table." },
  { id: "fs-07", topic: "os-filesystems", q: "Indexed allocation (e.g. Unix inode):", options: ["Puts all block pointers in an index block (or a tree of them) — supports fast random access without external fragmentation", "Is the same as linked allocation", "Cannot handle large files", "Stores data in the directory"], answer: 0, exp: "Unix inodes use direct + single/double/triple indirect blocks for scalability." },
  { id: "fs-08", topic: "os-filesystems", q: "The Unix inode's indirect block scheme means large files use:", options: ["Only direct pointers", "Direct pointers for small files, then single, double, and triple indirect blocks for progressively larger files", "A single huge array", "Linked lists"], answer: 1, exp: "Small files are efficient (no indirection); huge files are still addressable." },
  { id: "fs-09", topic: "os-filesystems", q: "Free-space management commonly uses:", options: ["A bitmap (one bit per block: free/used) or a free-list", "The inode table", "The directory", "Nothing"], answer: 0, exp: "A bitmap makes finding contiguous runs easy; a free-list is compact when the disk is nearly full." },
  { id: "fs-10", topic: "os-filesystems", q: "Journaling file systems (ext4, NTFS, XFS) improve:", options: ["Read speed", "Crash consistency — metadata (and optionally data) changes are first written to a journal (write-ahead log), then applied, so a crash can be recovered by replaying/rolling back", "Compression", "Encryption"], answer: 1, exp: "It avoids a slow full fsck after an unclean shutdown." },
  { id: "fs-11", topic: "os-filesystems", q: "A copy-on-write file system (ZFS, Btrfs) never overwrites data in place; instead it:", options: ["Overwrites everything", "Writes new blocks and atomically switches the tree root — enabling snapshots and strong consistency", "Uses a journal only", "Cannot grow"], answer: 1, exp: "Snapshots are cheap because old blocks are simply retained." },
  { id: "fs-12", topic: "os-filesystems", q: "The file descriptor returned by open() is:", options: ["The inode number", "A per-process integer index into the process's file-descriptor table, which points to a system-wide open-file entry", "The disk block address", "The file size"], answer: 1, exp: "0, 1, 2 are stdin, stdout, stderr by convention." },
  { id: "fs-13", topic: "os-filesystems", q: "The file offset (file position) is stored in:", options: ["The inode", "The open-file table entry (shared by dup()'d fds and inherited across fork())", "The directory entry", "The process's registers"], answer: 1, exp: "Two separate open() calls on the same file get independent offsets." },
  { id: "fs-14", topic: "os-filesystems", q: "The 'everything is a file' Unix philosophy means:", options: ["All data is text", "Devices, pipes, sockets and kernel interfaces (/proc, /sys) are accessed through the same open/read/write/close API", "Files cannot be binary", "There are no directories"], answer: 1, exp: "A uniform interface simplifies tools and programs." },
  { id: "fs-15", topic: "os-filesystems", q: "Mounting a file system:", options: ["Formats it", "Attaches it into the existing directory tree at a mount point, so its root appears as that directory", "Deletes it", "Copies it to memory"], answer: 1, exp: "The VFS (virtual file system) layer lets many file-system types coexist." },
  { id: "fs-16", topic: "os-filesystems", q: "The VFS (Virtual File System) layer provides:", options: ["Disk encryption", "A common in-kernel interface (inodes, dentries, superblocks, file ops) so applications use one API regardless of the underlying file system", "Compression", "A journal"], answer: 1, exp: "ext4, NFS, FAT, etc. all implement the VFS operation set." },
  { id: "fs-17", topic: "os-filesystems", q: "Disk block size vs file system performance:", options: ["Larger blocks always win", "Larger blocks improve sequential throughput and reduce metadata but increase internal fragmentation for small files", "Block size is irrelevant", "Smaller blocks improve throughput"], answer: 1, exp: "Typical block sizes: 4 KB (matches the page size)." },
  { id: "fs-18", topic: "os-filesystems", q: "The buffer cache / page cache:", options: ["Stores CPU instructions", "Keeps recently used disk blocks/file pages in RAM so repeated accesses avoid disk I/O", "Is the swap area", "Is per-process only"], answer: 1, exp: "Writes are often buffered (write-back) and flushed later, or on fsync()." },
  { id: "fs-19", topic: "os-filesystems", q: "fsync() is used to:", options: ["Delete a file", "Force buffered writes for a file (and its metadata) to durable storage before returning", "Rename a file", "Lock a file"], answer: 1, exp: "Critical for databases and anything needing crash durability guarantees." },
  { id: "fs-20", topic: "os-filesystems", q: "Directory implementation with a linear list of entries:", options: ["Is O(1) lookup", "Is simple but O(n) to find/create/delete an entry — slow for huge directories", "Uses a B-tree", "Cannot be sorted"], answer: 1, exp: "Modern file systems use hash tables (ext4 htree) or B-trees (XFS, NTFS) for directories." },
  { id: "fs-21", topic: "os-filesystems", q: "The link count in an inode reaching zero (and no process has it open) means:", options: ["The file is read-only", "The file's data blocks and inode are freed", "The file is compressed", "It becomes a directory"], answer: 1, exp: "'Deleting' a file is really unlink() — it removes one name; data goes when count is 0 AND no open fds." },
  { id: "fs-22", topic: "os-filesystems", q: "A file opened by a process, then unlink()ed by another:", options: ["Causes an error", "Remains accessible to the first process until it closes the fd; the space is reclaimed after the last close", "Is immediately gone", "Cannot happen"], answer: 1, exp: "This is how temp files and atomic replace-by-rename work." },
  { id: "fs-23", topic: "os-filesystems", q: "The superblock of a file system contains:", options: ["File data", "File-system-wide metadata: size, block size, free-block/inode counts, location of key structures", "One file's inode", "The directory tree"], answer: 1, exp: "It is usually replicated for redundancy." },
  { id: "fs-24", topic: "os-filesystems", q: "Disk scheduling algorithm SSTF (Shortest Seek Time First):", options: ["Serves requests in arrival order", "Serves the request closest to the current head position next — reduces average seek but can starve far requests", "Sweeps end to end", "Is random"], answer: 1, exp: "SCAN/LOOK (elevator) avoid starvation by sweeping in one direction." },
  { id: "fs-25", topic: "os-filesystems", q: "The SCAN (elevator) disk-scheduling algorithm:", options: ["Jumps randomly", "Moves the head in one direction servicing requests, then reverses — bounded waiting, good throughput", "Is the same as FCFS", "Only works on SSDs"], answer: 1, exp: "C-SCAN services in one direction only (then jumps back), giving more uniform wait times." },
  { id: "fs-26", topic: "os-filesystems", q: "On an SSD, disk-head scheduling algorithms:", options: ["Are more important than ever", "Matter far less (no seek time); the FTL, write amplification, and TRIM/garbage collection dominate instead", "Cause data loss", "Are required by the standard"], answer: 1, exp: "SSDs favor large sequential writes and dislike small random writes (wear, amplification)." },
  { id: "fs-27", topic: "os-filesystems", q: "The TRIM command tells an SSD:", options: ["To speed up", "Which blocks are no longer in use by the file system, so its garbage collector can reclaim them efficiently", "To encrypt data", "To defragment"], answer: 1, exp: "Without TRIM the SSD thinks deleted blocks still hold valid data." },
  { id: "fs-28", topic: "os-filesystems", q: "File-system fragmentation on an HDD hurts performance because:", options: ["It wastes CPU", "A fragmented file's blocks are scattered, requiring many seeks for sequential reads", "It corrupts data", "It fills the inode table"], answer: 1, exp: "Defragmentation relocates blocks to be contiguous; largely unnecessary on SSDs." },
  { id: "fs-29", topic: "os-filesystems", q: "The difference between a block device and a character device:", options: ["Block devices are faster", "Block devices (disks) are accessed in fixed-size blocks with buffering/random access; character devices (keyboard, serial) are byte streams", "Character devices store more", "They are the same"], answer: 1, exp: "Both appear as special files in /dev." },
  { id: "fs-30", topic: "os-filesystems", q: "A file system's 'lost+found' directory holds:", options: ["Deleted files", "Files/inodes recovered by fsck that had no valid directory entry (orphaned)", "System logs", "Temporary files"], answer: 1, exp: "fsck reconnects orphaned inodes there after a crash." },
  { id: "fs-31", topic: "os-filesystems", q: "Access control on Unix files uses:", options: ["ACLs only", "Owner/group/other with read/write/execute bits (and optionally extended ACLs)", "Passwords per file", "Encryption"], answer: 1, exp: "The setuid/setgid/sticky bits add special semantics." },
  { id: "fs-32", topic: "os-filesystems", q: "The sticky bit on a directory (e.g. /tmp):", options: ["Makes it read-only", "Lets any user create files, but only the file's owner (or root) can delete/rename their own files", "Prevents new files", "Compresses the directory"], answer: 1, exp: "Without it, anyone with write on /tmp could delete anyone's temp files." },
  { id: "fs-33", topic: "os-filesystems", q: "A RAID controller and a file system's redundancy features:", options: ["Are the same thing", "RAID operates at the block level (mirroring/parity across disks); the file system operates at the file/metadata level — some FSes (ZFS) integrate both", "Cannot coexist", "Both compress"], answer: 1, exp: "Integrated FS+RAID (ZFS, Btrfs) can detect and repair silent corruption via checksums." },
  { id: "fs-34", topic: "os-filesystems", q: "Data-block checksums in a file system detect:", options: ["Slow disks", "Silent data corruption (bit rot, misdirected writes) — the FS can then repair from a redundant copy", "Fragmentation", "Full disks"], answer: 1, exp: "ext4 checksums metadata; ZFS/Btrfs checksum data too." },
  { id: "fs-35", topic: "os-filesystems", q: "The maximum file size in a file system is limited by:", options: ["The disk speed", "The size of the block-pointer fields and the allocation scheme (e.g. direct + indirect blocks, or extent trees)", "The number of files", "The directory depth"], answer: 1, exp: "ext4 uses extents (start + length) instead of block lists for large files." },
  { id: "fs-36", topic: "os-filesystems", q: "An extent is:", options: ["A single block", "A contiguous run of blocks described by (start block, length) — far more compact than a per-block pointer list for large files", "An inode", "A directory"], answer: 1, exp: "Extent-based FSes (ext4, XFS, NTFS) reduce metadata and fragmentation." },
  { id: "fs-37", topic: "os-filesystems", q: "The 'noatime' mount option:", options: ["Disables the file system", "Stops updating each file's access-time on every read, reducing write traffic", "Disables timestamps entirely", "Speeds up seeks"], answer: 1, exp: "'relatime' is a middle ground (update atime only if older than mtime/ctime or > 24h)." },
  { id: "fs-38", topic: "os-filesystems", q: "A log-structured file system (LFS):", options: ["Writes randomly", "Treats the whole disk as a sequential append-only log, buffering writes and flushing them as large sequential segments — great write throughput, needs a cleaner", "Cannot be read", "Has no metadata"], answer: 1, exp: "The idea influenced SSD FTLs and systems like F2FS." },
  { id: "fs-39", topic: "os-filesystems", q: "Which operation is atomic on most POSIX file systems and used for safe file updates?", options: ["write()", "rename() over an existing file (write to temp, fsync, rename temp -> target)", "truncate()", "unlink()"], answer: 1, exp: "rename() atomically replaces the target so readers never see a partial file." },
  { id: "fs-40", topic: "os-filesystems", q: "The page cache holds file data; the dentry cache holds:", options: ["Disk blocks", "Directory-entry lookups (name -> inode), speeding path resolution", "Inodes only", "Free-space info"], answer: 1, exp: "Path resolution walks components; caching avoids repeated directory reads." },
  { id: "fs-41", topic: "os-filesystems", q: "A network file system (NFS) presents a remote file system as local by:", options: ["Copying all files locally", "Forwarding file operations as RPCs to the server; caching and consistency are the hard parts", "Using a USB cable", "Compressing the network"], answer: 1, exp: "NFSv3 is stateless; NFSv4 adds state, delegations and better security." },
  { id: "fs-42", topic: "os-filesystems", q: "FUSE (Filesystem in Userspace) allows:", options: ["Only kernel developers to add file systems", "A user-space program to implement a file system, with the kernel forwarding VFS calls to it (sshfs, encfs, s3fs)", "Faster disk access", "Encryption only"], answer: 1, exp: "Slower than in-kernel FS due to context switches, but easy to develop." },
  { id: "fs-43", topic: "os-filesystems", q: "The 'df' vs 'du' discrepancy (df shows more used space than du sums) is often caused by:", options: ["A bug", "Files that were deleted (unlinked) while still open by a running process — space is not reclaimed until the fd closes", "Compression", "Symbolic links"], answer: 1, exp: "lsof +L1 finds such deleted-but-open files." },
  { id: "fs-44", topic: "os-filesystems", q: "Sparse files:", options: ["Have no data", "Report a large logical size but only allocate blocks for the regions actually written; unwritten 'holes' read as zeros", "Cannot be created", "Are always compressed"], answer: 1, exp: "Common for VM disk images and database files; 'cp --sparse' preserves them." },
  { id: "fs-45", topic: "os-filesystems", q: "The order 'write data, then update metadata' matters for crash consistency because:", options: ["It is faster", "If metadata (e.g. a block pointer) is written before the data, a crash leaves the file pointing at garbage; journaling / ordered mode enforces safe ordering", "It saves space", "It is required by SSDs"], answer: 1, exp: "ext4 'data=ordered' forces data out before the metadata that references it." },
  { id: "fs-46", topic: "os-filesystems", q: "Which is TRUE about hard links and inodes across file systems?", options: ["Hard links can span file systems", "A hard link cannot span file systems because inode numbers are only unique within one file system", "Symlinks cannot span file systems", "Neither can span"], answer: 1, exp: "Symbolic links CAN span file systems (they store a path, resolved at use time)." },
  { id: "fs-47", topic: "os-filesystems", q: "The number of inodes in a traditional file system is:", options: ["Unlimited", "Fixed at format time (you can run out of inodes even with free disk space, e.g. millions of tiny files)", "Grown automatically always", "Equal to the block count"], answer: 1, exp: "Modern FSes (XFS, Btrfs, ZFS) allocate inodes dynamically." },
  { id: "fs-48", topic: "os-filesystems", q: "A file lock (flock / fcntl) is:", options: ["Mandatory always", "Usually ADVISORY on Unix — cooperating processes must check it; the OS does not enforce it against non-checking programs", "A hardware feature", "Stored in the file's data"], answer: 1, exp: "Windows uses mandatory locking; Unix mandatory locking is rare and discouraged." },
  { id: "fs-49", topic: "os-filesystems", q: "The purpose of the 'dirty page writeback' daemon (pdflush/kworker/flush):", options: ["To read files", "To asynchronously flush modified page-cache pages to disk based on age and dirty-ratio thresholds", "To defragment", "To check permissions"], answer: 1, exp: "It bounds data loss on a crash and smooths I/O; fsync() forces immediate writeback for one file." },
  { id: "fs-50", topic: "os-filesystems", q: "Overall, a file system must provide:", options: ["Only storage", "A namespace (directories), allocation of blocks to files, metadata management, access control, and crash consistency", "Only speed", "Encryption"], answer: 1, exp: "It is the OS component that turns a raw block device into a usable, reliable store of named data." }

);


